package com.cabosschecklist;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.image.BufferedImage;
import java.util.function.BooleanSupplier;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.LinkBrowser;

/**
 * The boss card under the search box: the wiki's picture in a 64 x 64 box, the boss's long name, its progress, a box
 * that says whether the boss shows green in the Tasks menu, and under it the note row: the tag (the word {@link MarkTag#TEXT}) and some
 * words, shown only when the boss has a mark or the hint "Tick to show it green" applies, and taking no height at all
 * when hidden. Everything is centred.
 * Choice: the picture box and its 6 px gap are one holder that is hidden together; the note row holds its own 4 px gap
 * above, so hiding the row hides the gap.
 */
final class BossCard extends JPanel
{
	/** The card's padding, in px. */
	private static final int PADDING = 8;
	/** The picture box's side, in px. */
	private static final int BOX = 64;
	/** The width the name must fit, in px. */
	private static final int NAME_WIDTH = 203;
	/** The name's sizes, largest first; the last is the one that is cut with "..." when it still does not fit. */
	private static final float[] NAME_SIZES = {13f, 12f, 11f};

	private final MarkActions actions;
	private final BooleanSupplier wikiPictures;
	private final WikiPictures pictures;
	private final JPanel pictureHolder = new JPanel();
	private final JLabel picture = new JLabel("", SwingConstants.CENTER);
	private final JLabel name = ViewParts.centred("", ViewParts.bold(13f), Color.WHITE);
	private final JLabel progress = ViewParts.centred("", ViewParts.plain(12f), ColorScheme.LIGHT_GRAY_COLOR);
	private final JCheckBox green = new JCheckBox("Green in the Tasks menu");
	private final MarkTag tag = new MarkTag();
	/** The words after the tag; never squeezed in height, or BoxLayout would give a lone one half its height. */
	private final JLabel words = new JLabel()
	{
		@Override
		public Dimension getMinimumSize()
		{
			return new Dimension(0, getPreferredSize().height);
		}
	};
	private final JPanel noteRow = ViewParts.capped(null);
	private final LinkLabel wiki = new LinkLabel("Wiki", 11f, this::openWiki);
	/** The boss on the card; null before the first draw. */
	private ChecklistView.Boss shown;

	BossCard(MarkActions actions, BooleanSupplier wikiPictures, WikiPictures pictures)
	{
		this.actions = actions;
		this.wikiPictures = wikiPictures;
		this.pictures = pictures;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(PADDING, PADDING, PADDING, PADDING));

		final Dimension box = new Dimension(BOX, BOX);
		picture.setMinimumSize(box);
		picture.setPreferredSize(box);
		picture.setMaximumSize(box);
		picture.setAlignmentX(Component.CENTER_ALIGNMENT);
		pictureHolder.setLayout(new BoxLayout(pictureHolder, BoxLayout.Y_AXIS));
		pictureHolder.setOpaque(false);
		pictureHolder.setAlignmentX(Component.CENTER_ALIGNMENT);
		pictureHolder.add(picture);
		pictureHolder.add(Box.createVerticalStrut(6));

		green.setFont(ViewParts.plain(12f));
		green.setForeground(Color.WHITE);
		green.setOpaque(false);
		green.setFocusable(false);
		green.setAlignmentX(Component.CENTER_ALIGNMENT);
		green.addActionListener(e ->
		{
			if (shown != null)
			{
				actions.flip(shown.id);
			}
		});

		add(pictureHolder);
		add(name);
		add(Box.createVerticalStrut(4));
		add(progress);
		add(Box.createVerticalStrut(6));
		add(green);
		buildNoteRow();
		add(noteRow);
		wiki.setAlignmentX(Component.CENTER_ALIGNMENT);
		add(Box.createVerticalStrut(4));
		add(wiki);
	}

	/** The note row: a 4 px gap, then the tag and its words on one line, centred together, at most {@link #NAME_WIDTH} wide. */
	private void buildNoteRow()
	{
		noteRow.setLayout(new BoxLayout(noteRow, BoxLayout.Y_AXIS));
		noteRow.setOpaque(false);
		noteRow.setAlignmentX(Component.CENTER_ALIGNMENT);
		final JPanel line = new JPanel()
		{
			@Override
			public Dimension getPreferredSize()
			{
				final Dimension size = super.getPreferredSize();
				return new Dimension(Math.min(size.width, NAME_WIDTH), size.height);
			}

			/** As wide as the column: BoxLayout would give a narrower, centre-aligned part half its width at the left. */
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		line.setLayout(new BoxLayout(line, BoxLayout.X_AXIS));
		line.setOpaque(false);
		line.setAlignmentX(Component.CENTER_ALIGNMENT);
		tag.setAlignmentY(Component.CENTER_ALIGNMENT);
		words.setAlignmentY(Component.CENTER_ALIGNMENT);
		words.setBorder(new EmptyBorder(0, 4, 0, 0));
		words.setFont(ViewParts.plain(11f));
		words.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		line.add(Box.createHorizontalGlue());
		line.add(tag);
		line.add(words);
		line.add(Box.createHorizontalGlue());
		noteRow.add(Box.createVerticalStrut(4));
		noteRow.add(line);
		noteRow.setVisible(false);
	}

	/** Opens the shown boss's wiki page at its Combat Achievements table; nothing before a boss is shown. */
	private void openWiki()
	{
		if (shown != null)
		{
			LinkBrowser.browse(BossPictures.wikiUrl(shown.id, shown.name));
		}
	}

	/** As wide as the column it sits in, never taller than its content. */
	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	/** Draws {@code boss} (of {@code view}) on the card. */
	void show(ChecklistView view, ChecklistView.Boss boss)
	{
		shown = boss;
		fitName(boss.name);
		progress.setText(boss.progressLine());
		green.setSelected(boss.green);
		final ChecklistView.CardNote note = view.cardNote(boss);
		noteRow.setVisible(note != ChecklistView.CardNote.NONE);
		tag.setVisible(note.tag);
		tag.setStrong(note.strong);
		words.setText(note.text);
		words.setVisible(!note.text.isEmpty());
		drawPicture();
		revalidate();
		repaint();
	}

	/** Reads the shown boss's picture again, after the wiki answered for some title. */
	void pictureArrived()
	{
		if (shown != null)
		{
			drawPicture();
			revalidate();
			repaint();
		}
	}

	/**
	 * The picture rule: with the wiki switch on and a wiki title for the boss, ask for the title (once) and show its
	 * picture when kept; when the wiki had none, hide the box and its gap; while the answer is on its way, show the empty
	 * box. With the switch off or no title, the box is hidden.
	 */
	private void drawPicture()
	{
		final String title = wikiPictures.getAsBoolean() ? BossPictures.titleFor(shown.id, shown.name) : null;
		if (title == null)
		{
			showBox(false, null);
			return;
		}
		pictures.fetch(title);
		final BufferedImage image = pictures.pictureOf(title);
		if (image != null)
		{
			showBox(true, new ImageIcon(image));
		}
		else
		{
			showBox(!pictures.isAnswered(title), null);
		}
	}

	private void showBox(boolean visible, ImageIcon icon)
	{
		picture.setIcon(icon);
		picture.setVisible(visible);
		pictureHolder.setVisible(visible);
	}

	/** Sets the name at the largest of 13, 12 and 11 px at which it fits, else cut with "..." at 11. */
	private void fitName(String text)
	{
		for (float size : NAME_SIZES)
		{
			final Font font = ViewParts.bold(size);
			if (name.getFontMetrics(font).stringWidth(text) <= NAME_WIDTH)
			{
				name.setFont(font);
				name.setText(text);
				return;
			}
		}
		final Font font = ViewParts.bold(NAME_SIZES[NAME_SIZES.length - 1]);
		name.setFont(font);
		String cut = text;
		while (!cut.isEmpty() && name.getFontMetrics(font).stringWidth(cut + "...") > NAME_WIDTH)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		name.setText(cut.trim() + "...");
	}
}

package com.cabosschecklist;

import okhttp3.HttpUrl;

/**
 * Which wiki page's picture stands for a boss of the game's Monster list. Checked on 2026-11-08: the game's long names
 * (enum 3971) give a PNG picture for 86 of the 92 bosses. The rest are the table in {@link #titleFor}; "The Mad Angel"
 * has only a WebP picture and "Giants" none, so their cards show none.
 */
final class BossPictures
{
	private BossPictures()
	{
	}

	/**
	 * The wiki page whose picture stands for the boss, or null for none. Id 14 (Chambers of Xeric: CM) is the page
	 * "Chambers of Xeric"; ids 54 and 56 (Theatre of Blood: Entry Mode and Hard Mode, whose own pages have no picture)
	 * are "Theatre of Blood"; id 76 ("Other") has none. Any other boss is the page of its {@code name}, or none when the
	 * name is null or blank.
	 */
	static String titleFor(int id, String name)
	{
		if (id == 14)
		{
			return "Chambers of Xeric";
		}
		if (id == 54 || id == 56)
		{
			return "Theatre of Blood";
		}
		if (id == 76)
		{
			return null;
		}
		return name == null || name.trim().isEmpty() ? null : name;
	}

	/**
	 * The wiki address of the boss's Combat Achievements: the page is "Chambers of Xeric/Challenge Mode" for id 14,
	 * "Combat Achievements" for id 76 (Other), else {@code name}; every id but 76 ends at the page's table, the
	 * fragment "Combat_Achievements". Checked on 2026-11-11: all 91 long names against the wiki's API, where only
	 * "Chambers of Xeric: CM" and "Other" are not pages; the table's anchor on 11 of 13 sampled pages (a page
	 * without it opens at its top).
	 */
	static String wikiUrl(int id, String name)
	{
		final String page = id == 14 ? "Chambers of Xeric/Challenge Mode" : id == 76 ? "Combat Achievements" : name;
		final HttpUrl.Builder url = new HttpUrl.Builder()
			.scheme("https")
			.host("oldschool.runescape.wiki")
			.addPathSegment("w");
		for (String part : page.split("/"))
		{
			url.addPathSegment(part.replace(' ', '_'));
		}
		if (id != 76)
		{
			url.fragment("Combat_Achievements");
		}
		return url.build().toString();
	}
}

package com.cabosschecklist;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.function.IntConsumer;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.IconTextField;

/**
 * The Bosses view: a search box, and one row per boss that the search leaves, a box that shows whether the boss is green,
 * its label and its status. The rows are built once per list of ids and then updated in place, so the scroll position and
 * the mouse state survive an update. Typing in the search box filters the list and chooses the first boss left; a press
 * on a row chooses that boss, and a press on the chosen row takes the choice off. The chosen boss's card and task list
 * form one panel that the list holds right after the boss's row, 2 px below it.
 * Choice: the opened panel is in the list only while a boss is chosen, so a closed one holds no component, and it moves
 * to its place on each draw; a chosen row keeps its chosen ground under the mouse.
 */
final class BossesView extends JPanel
{
	/** The space between rows, in px. */
	private static final int ROW_GAP = 2;
	/** The space between the search box and the list, and between the card and the task list, in px. */
	private static final int GAP = 6;
	/** The search box's height, in px. */
	private static final int SEARCH_HEIGHT = 30;

	/** One boss's row: the box, the label and the status word. */
	private static final class Row
	{
		final JPanel panel = ViewParts.capped(new BorderLayout(4, 0));
		final JCheckBox box = new JCheckBox();
		final JLabel name = ViewParts.label("", ViewParts.bold(12f), Color.WHITE);
		final JLabel status = ViewParts.quiet("");
		private boolean chosen;
		private boolean hovered;

		Row(int id, MarkActions actions, IntConsumer pressed)
		{
			panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
			panel.setBorder(new EmptyBorder(4, 4, 4, 6));
			box.setOpaque(false);
			box.setFocusable(false);
			box.addActionListener(e -> actions.flip(id));
			panel.add(box, BorderLayout.WEST);
			panel.add(name, BorderLayout.CENTER);
			panel.add(status, BorderLayout.EAST);
			panel.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (HalfToggle.isPress(e))
					{
						pressed.accept(id);
					}
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					hovered = true;
					paintGround();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					hovered = false;
					paintGround();
				}
			});
		}

		void update(ChecklistView.Boss boss, boolean isChosen)
		{
			box.setSelected(boss.green);
			name.setText(boss.label);
			name.setForeground(ViewParts.colourOf(boss.shade));
			status.setText(boss.status());
			chosen = isChosen;
			paintGround();
		}

		/** The chosen row is medium grey, a row under the mouse is the hover grey, any other the dark grey. */
		private void paintGround()
		{
			panel.setBackground(chosen ? ColorScheme.MEDIUM_GRAY_COLOR
				: hovered ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARK_GRAY_COLOR);
		}
	}

	private final MarkActions actions;
	private final ScrollColumn column = new ScrollColumn();
	private final JScrollPane pane = column.pane();
	private final List<Row> rows = new ArrayList<>();
	private final IconTextField search = new IconTextField();
	private final BossCard card;
	private final TaskList taskList = new TaskList();
	/** The chosen boss's card and task list on the dark grey ground, inside a holder that adds the 2 px above it. */
	private final JPanel opened = ViewParts.capped(new BorderLayout());
	private final JPanel top = new JPanel();
	private final Component searchGap = Box.createVerticalStrut(GAP);
	/** The ids the rows were built for, in order; null while the column holds something else. */
	private List<Integer> shownIds;
	/** The last view; null while logged out. */
	private ChecklistView view;
	/** The search text, as typed. */
	private String query = "";
	/** The id of the boss on the card; null when the card is hidden. */
	private Integer chosen;
	/** Set while this view writes the search box itself, so its own writes are not taken as typing. */
	private boolean writing;

	BossesView(MarkActions actions, BooleanSupplier wikiPictures, WikiPictures pictures)
	{
		super(new BorderLayout());
		this.actions = actions;
		this.card = new BossCard(actions, wikiPictures, pictures);
		setOpaque(false);

		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(0, SEARCH_HEIGHT));
		search.setBackground(ColorScheme.DARK_GRAY_COLOR);
		search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		search.setAlignmentX(Component.LEFT_ALIGNMENT);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				typed();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				typed();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				typed();
			}
		});
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		taskList.setAlignmentX(Component.LEFT_ALIGNMENT);
		final JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		body.add(card);
		body.add(Box.createVerticalStrut(GAP));
		body.add(taskList);
		opened.setOpaque(false);
		opened.setBorder(new EmptyBorder(ROW_GAP, 0, 0, 0));
		opened.add(body, BorderLayout.CENTER);

		// The search box ends where the panel's header does, so every right edge lines up.
		final int bar = pane.getVerticalScrollBar().getPreferredSize().width;
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		top.setOpaque(false);
		top.setBorder(new EmptyBorder(0, 0, 0, bar));
		top.add(search);
		top.add(searchGap);
		add(top, BorderLayout.NORTH);
		add(pane, BorderLayout.CENTER);
		top.setVisible(false);
	}

	/** The scroll pane inside this view (its bar's width is the header's right inset). */
	JScrollPane pane()
	{
		return pane;
	}

	/** Hides the search box, clears the text and the choice, and replaces the rows with one grey line. */
	void showLoggedOut()
	{
		view = null;
		chosen = null;
		query = "";
		writing = true;
		search.setText("");
		writing = false;
		top.setVisible(false);
		shownIds = null;
		rows.clear();
		column.removeAll();
		showLine("Log in to see your bosses");
	}

	/** Shows the view's bosses that the search leaves; the rows are kept while the ids (in order) are the same. */
	void show(ChecklistView next)
	{
		view = next;
		top.setVisible(true);
		draw();
	}

	/** Passes a finished wiki answer on to the card. */
	void pictureArrived()
	{
		card.pictureArrived();
	}

	/** The search text changed: a blank one shows every boss and chooses none, else the first boss left is chosen. */
	private void typed()
	{
		if (writing)
		{
			return;
		}
		query = search.getText();
		chosen = null;
		if (view != null && !query.trim().isEmpty())
		{
			final List<ChecklistView.Boss> left = filtered();
			chosen = left.isEmpty() ? null : left.get(0).id;
		}
		if (view != null)
		{
			draw();
		}
	}

	/** A press on a row: the pressed boss is chosen, or not any more when it already was. */
	private void pressed(int id)
	{
		chosen = chosen != null && chosen == id ? null : Integer.valueOf(id);
		draw();
	}

	/** The view's bosses that match the search text, in row order. */
	private List<ChecklistView.Boss> filtered()
	{
		final List<ChecklistView.Boss> left = new ArrayList<>();
		for (ChecklistView.Boss boss : view.bosses)
		{
			if (boss.matches(query))
			{
				left.add(boss);
			}
		}
		return left;
	}

	/** Draws the rows, their grounds and the opened panel from the last view, the text and the choice. */
	private void draw()
	{
		final List<ChecklistView.Boss> left = filtered();
		ChecklistView.Boss onCard = null;
		int chosenAt = -1;
		for (int i = 0; i < left.size(); i++)
		{
			if (chosen != null && left.get(i).id == chosen)
			{
				onCard = left.get(i);
				chosenAt = i;
			}
		}
		if (onCard == null)
		{
			chosen = null;
		}
		else
		{
			card.show(view, onCard);
			taskList.show(onCard.id, view.tasksOf(onCard.id));
		}
		if (opened.getParent() == column)
		{
			column.remove(opened);
		}

		if (left.isEmpty())
		{
			shownIds = null;
			rows.clear();
			column.removeAll();
			showLine("No boss matches");
			return;
		}
		final List<Integer> ids = new ArrayList<>();
		for (ChecklistView.Boss boss : left)
		{
			ids.add(boss.id);
		}
		if (!ids.equals(shownIds))
		{
			column.removeAll();
			rows.clear();
			for (int i = 0; i < ids.size(); i++)
			{
				if (i > 0)
				{
					column.add(Box.createVerticalStrut(ROW_GAP));
				}
				final Row row = new Row(ids.get(i), actions, this::pressed);
				rows.add(row);
				column.add(row.panel);
			}
			shownIds = ids;
			column.revalidate();
		}
		for (int i = 0; i < rows.size(); i++)
		{
			final ChecklistView.Boss boss = left.get(i);
			rows.get(i).update(boss, chosen != null && boss.id == chosen);
		}
		if (chosenAt >= 0)
		{
			// Row i sits at component 2 * i of the column (a gap comes before every row but the first).
			column.add(opened, 2 * chosenAt + 1);
		}
		column.revalidate();
		column.repaint();
	}

	/** Replaces the column's content with one grey line. */
	private void showLine(String text)
	{
		final JLabel line = ViewParts.centred(text, ViewParts.plain(12f), ColorScheme.LIGHT_GRAY_COLOR);
		line.setBorder(new EmptyBorder(16, 0, 0, 0));
		column.add(line);
		column.revalidate();
		column.repaint();
	}
}

package com.cabosschecklist;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

/**
 * The plugin's settings. Flat on purpose: every item is declared here and this interface extends {@link Config}
 * alone, because RuneLite stores defaults only for the methods declared on the interface it is given. The group and
 * the keys are frozen at first release; renaming one silently discards every player's setting.
 *
 * <p>The player's per-boss marks are not an item: they live in the RuneScape profile under {@link #MARKS_KEY}, one
 * string per account, written by the sidebar, and so are the marks the player has seen, under {@link #SEEN_KEY}.
 */
@ConfigGroup(CaBossChecklistConfig.GROUP)
public interface CaBossChecklistConfig extends Config
{
	String GROUP = "ca-boss-checklist";

	/** The switch that turns a name green once the account has done every task for it. */
	String AUTO_DETECT_KEY = "autoDetect";

	/** The switch that turns a name yellow when one or two of its tasks are left. */
	String ALMOST_DONE_KEY = "almostDone";

	/** The switch that shows the wiki's picture of a boss on its card. */
	String WIKI_PICTURES_KEY = "wikiPictures";

	/** The switch that shows the plugin's sidebar button. */
	String SHOW_SIDEBAR_KEY = "showSidebar";

	/** The drop-down that picks the sidebar button's picture. */
	String SIDEBAR_ICON_KEY = "sidebarIcon";

	/** The profile key holding the account's marks, "id=token" entries joined by commas (see {@link Marks}). */
	String MARKS_KEY = "marks";

	/** The profile key holding the overriding marks the player has looked at, in the same form as the marks. */
	String SEEN_KEY = "seenMarks";

	@ConfigItem(
		keyName = AUTO_DETECT_KEY,
		name = "Green when all tasks done",
		description = "Show a name green once every task for it is done.",
		position = 0
	)
	default boolean autoDetect()
	{
		return true;
	}

	@ConfigItem(
		keyName = ALMOST_DONE_KEY,
		name = "Yellow when almost done",
		description = "Show a name yellow in the Tasks menu when one or two of its tasks are left.",
		position = 1
	)
	default boolean almostDone()
	{
		return true;
	}

	@ConfigItem(
		keyName = WIKI_PICTURES_KEY,
		name = "Wiki pictures",
		description = "Show the wiki's own picture of a boss on its card. Sends only the boss's name to oldschool.runescape.wiki, then fetches the picture the wiki names.",
		position = 2
	)
	default boolean wikiPictures()
	{
		return true;
	}

	@ConfigItem(
		keyName = SHOW_SIDEBAR_KEY,
		name = "Show the sidebar button",
		description = "Off: the button is hidden and names follow your account only. "
			+ "Your marks are kept for when you turn it back on.",
		position = 3
	)
	default boolean showSidebar()
	{
		return true;
	}

	@ConfigItem(
		keyName = SIDEBAR_ICON_KEY,
		name = "Sidebar icon",
		description = "Which picture the plugin's sidebar button shows.",
		position = 4
	)
	default SidebarIcon sidebarIcon()
	{
		return SidebarIcon.COIN_AND_BOOK;
	}

	/** The pictures the sidebar button can show; each is shown as its words. */
	enum SidebarIcon
	{
		COIN_AND_BOOK("2h coin and book"),
		BOOK("Book only"),
		COIN_AND_LETTERS("2h coin and CA letters");

		private final String words;

		SidebarIcon(String words)
		{
			this.words = words;
		}

		@Override
		public String toString()
		{
			return words;
		}
	}
}

