	/** Reads this account's marks and the marks it has seen from the RuneScape profile. */
	private void reloadMarks()
	{
		marks = Marks.parse(configManager.getRSProfileConfiguration(CaBossChecklistConfig.GROUP, CaBossChecklistConfig.MARKS_KEY));
		seen = Marks.parse(configManager.getRSProfileConfiguration(CaBossChecklistConfig.GROUP,
			CaBossChecklistConfig.SEEN_KEY));
	}

	/** Asks the EDT to draw the newest state. */
	private void pushView()
	{
		SwingUtilities.invokeLater(this::refreshPanel);
	}

	/** A wiki answer came in on any thread: asks the EDT to let the card read its picture again. */
	private void pictureArrived()
	{
		final CaBossChecklistPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(target::pictureArrived);
		}
	}

	/** Draws the state as it is now, so the last post always shows the newest state (EDT). */
	private void refreshPanel()
	{
		final CaBossChecklistPanel target = panel;
		if (target == null)
		{
			return;
		}
		final Map<Integer, CaCompletion.Progress> current = progress;
		if (current == null || configManager.getRSProfileKey() == null)
		{
			target.showLoggedOut();
		}
		else
		{
			target.show(ChecklistView.build(labels, names, current, marks, config.autoDetect(), config.almostDone(),
				seen).withTasks(taskLines));
		}
	}

	/** The sidebar's actions on the marks (EDT); each does nothing while logged out. */
	private final class Actions implements MarkActions
	{
		@Override
		public void flip(int id)
		{
			final Map<Integer, CaCompletion.Progress> current = progress;
			if (current == null || configManager.getRSProfileKey() == null)
			{
				return;
			}
			final boolean auto = config.autoDetect();
			final Set<Integer> complete = CaCompletion.completeIds(current);
			final Mark next = Marks.flip(Marks.isGreen(id, auto, complete, marks), complete.contains(id), auto);
			final Map<Integer, Mark> changed = new HashMap<>(marks);
			if (next == null)
			{
				changed.remove(id);
			}
			else
			{
				changed.put(id, next);
			}
			write(changed);
		}

		@Override
		public void remove(List<Integer> ids)
		{
			if (progress == null || configManager.getRSProfileKey() == null)
			{
				return;
			}
			final Map<Integer, Mark> changed = new HashMap<>(marks);
			changed.keySet().removeAll(ids);
			write(changed);
		}

		@Override
		public void remember(Map<Integer, Mark> next)
		{
			if (progress == null || configManager.getRSProfileKey() == null)
			{
				return;
			}
			store(CaBossChecklistConfig.SEEN_KEY, next);
		}

		/** Stores the marks; the ConfigChanged that follows reloads and redraws. */
		private void write(Map<Integer, Mark> next)
		{
			store(CaBossChecklistConfig.MARKS_KEY, next);
		}

		/** Stores {@code next} under {@code key} of the profile, or unsets the key when there is nothing to keep. */
		private void store(String key, Map<Integer, Mark> next)
		{
			final String value = Marks.format(next);
			if (value.isEmpty())
			{
				configManager.unsetRSProfileConfiguration(CaBossChecklistConfig.GROUP, key);
			}
			else
			{
				configManager.setRSProfileConfiguration(CaBossChecklistConfig.GROUP, key, value);
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			recompute = true;
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			completeMonsters = Collections.emptySet();
			completeTiers = Collections.emptySet();
			if (state == GameState.LOGIN_SCREEN)
			{
				originalColours.clear();
				progress = null;
				taskLines = Collections.emptyMap();
				pushView();
			}
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (contains(COMPLETED_VARPS, event.getVarpId()) || contains(TIER_STATUS_VARBITS, event.getVarbitId())
			|| event.getVarbitId() == VarbitID.GIM_GROUPSIZE)
		{
			recompute = true;
		}
	}

	private static boolean contains(int[] ids, int id)
	{
		for (int candidate : ids)
		{
			if (candidate == id)
			{
				return true;
			}
		}
		return false;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CaBossChecklistConfig.GROUP.equals(event.getGroup()))
		{
			reloadMarks();
			recompute = true;
			pushView();
			if (CaBossChecklistConfig.SIDEBAR_ICON_KEY.equals(event.getKey()))
			{
				SwingUtilities.invokeLater(this::applyIcon);
			}
			if (CaBossChecklistConfig.SHOW_SIDEBAR_KEY.equals(event.getKey()))
			{
				SwingUtilities.invokeLater(this::applySidebar);
			}
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		reloadMarks();
		pushView();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!recompute || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (tasks.isEmpty())
		{
			loadTasks();
		}
		final int[] varps = new int[COMPLETED_VARPS.length];
		for (int i = 0; i < varps.length; i++)
		{
			varps[i] = client.getVarpValue(COMPLETED_VARPS[i]);
		}
		final boolean deadman = client.getWorldType().contains(WorldType.DEADMAN);
		final int groupSize = client.getVarbitValue(VarbitID.GIM_GROUPSIZE);
		final Map<Integer, CaCompletion.Progress> read =
			Collections.unmodifiableMap(CaCompletion.progress(tasks, varps, deadman, groupSize));
		completeMonsters = CaCompletion.completeIds(read);
		progress = read;
		taskLines = Collections.unmodifiableMap(
			CaCompletion.taskLines(tasks, texts, tierWords, typeWords, varps, deadman, groupSize));
		final Set<Integer> tiers = new HashSet<>();
		for (int i = 0; i < TIER_STATUS_VARBITS.length; i++)
		{
			if (client.getVarbitValue(TIER_STATUS_VARBITS[i]) == 2)
			{
				tiers.add(i + 1);
			}
		}
		completeTiers = tiers;
		pushView();
		recompute = false;
	}

	/** Reads every task's four params from the game's task lists. */
	private void loadTasks()
	{
		final List<CaCompletion.Task> loaded = new ArrayList<>();
		final Map<Integer, CaCompletion.TaskText> loadedTexts = new HashMap<>();
		for (int enumId : TASK_ENUMS)
		{
			for (int structId : client.getEnum(enumId).getIntVals())
			{
				final StructComposition struct = client.getStructComposition(structId);
				final int taskId = struct.getIntValue(PARAM_TASK_ID);
				loaded.add(new CaCompletion.Task(
					taskId,
					struct.getIntValue(PARAM_MONSTER_ID),
					struct.getIntValue(PARAM_GIM_MAX_GROUP_SIZE),
					struct.getIntValue(PARAM_DEADMAN_SKIPPED)));
				loadedTexts.put(taskId, new CaCompletion.TaskText(
					struct.getStringValue(PARAM_TASK_NAME),
					struct.getStringValue(PARAM_TASK_DESCRIPTION),
					struct.getIntValue(PARAM_TASK_TIER),
					struct.getIntValue(PARAM_TASK_TYPE)));
			}
		}
		texts = loadedTexts;
		tierWords = words(TIER_WORD_ENUM);
		typeWords = words(TYPE_WORD_ENUM);
		tasks = loaded;
		final Map<Integer, String> loadedLabels = new LinkedHashMap<>();
		final EnumComposition monsters = client.getEnum(MONSTER_ENUM);
		for (int key : monsters.getKeys())
		{
			if (key > 0)
			{
				loadedLabels.put(key, monsters.getStringValue(key));
			}
		}
		final Map<Integer, String> loadedNames = new LinkedHashMap<>();
		final EnumComposition longNames = client.getEnum(MONSTER_NAME_ENUM);
		for (int key : longNames.getKeys())
		{
			if (key > 0)
			{
				loadedNames.put(key, longNames.getStringValue(key));
			}
		}
		names = Collections.unmodifiableMap(loadedNames);
		labels = Collections.unmodifiableMap(loadedLabels);
	}

	/** The words of an enum's keys 1 to 6. */
	private Map<Integer, String> words(int enumId)
	{
		final Map<Integer, String> loaded = new HashMap<>();
		final EnumComposition composition = client.getEnum(enumId);
		for (int key = 1; key <= 6; key++)
		{
			loaded.put(key, composition.getStringValue(key));
		}
		return loaded;
	}

	/** The game's hover script resets a row's colour while the mouse is over the list, so the colour is set every frame. */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		colourMenus();
	}

	/** The game's hover script runs after the client tick in a frame, so the colours are set again just before drawing. */
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		colourMenus();
	}

	/** Colours the open Monster and Tier lists' rows, and the chosen Monster's name in the boxes outside the list. */
	private void colourMenus()
	{
		final boolean autoDetect = config.autoDetect();
		final boolean almostDone = config.almostDone();
		final Map<Integer, Mark> markNow = Marks.inUse(marks, config.showSidebar());
		final Map<Integer, CaCompletion.Progress> progressNow = progress;
		final Widget monsters = client.getWidget(InterfaceID.CaTasks.DROPDOWN_MONSTER);
		if (monsters != null && !monsters.isHidden())
		{
			final Widget[] rows = monsters.getDynamicChildren();
			if (rows != null)
			{
				for (Widget row : rows)
				{
					final int id = CaCompletion.idForRow(row.getIndex());
					final CaCompletion.Shade shade = CaCompletion.shadeOf(id, autoDetect, almostDone, completeMonsters, markNow,
						progressNow);
					if (shade != CaCompletion.Shade.PLAIN)
					{
						row.setTextColor(colourOf(shade));
					}
				}
			}
		}
		colourChosenBoxes(autoDetect, almostDone, markNow, progressNow);
		final Widget tiers = client.getWidget(InterfaceID.CaTasks.DROPDOWN_TIER);
		if (tiers != null && !tiers.isHidden())
		{
			final Widget[] rows = tiers.getDynamicChildren();
			if (rows != null)
			{
				for (Widget row : rows)
				{
					final int id = CaCompletion.idForRow(row.getIndex());
					if (id >= 1 && id <= 6 && completeTiers.contains(id))
					{
						row.setTextColor(COMPLETE_COLOR);
					}
				}
			}
		}
	}

	private static int colourOf(CaCompletion.Shade shade)
	{
		return shade == CaCompletion.Shade.GREEN ? COMPLETE_COLOR : ALMOST_DONE_COLOR;
	}

	/**
	 * Gives the chosen Monster's name, where the game shows it outside the open list (the MONSTER_FILTER box and the
	 * DROPDOWN_BOX under the list), the colour that name has in the list. The chosen monster is the game's own filter
	 * varbit (scripts ca_task_updatetext 4833 and ca_task_filter_updatetext 4823 write the box from it, in full or cut
	 * with "..."); only a widget showing that monster's label is touched.
	 */
	private void colourChosenBoxes(boolean autoDetect, boolean almostDone, Map<Integer, Mark> markNow,
		Map<Integer, CaCompletion.Progress> progressNow)
	{
		final int id = client.getVarbitValue(VarbitID.CA_TASK_FILTER_MONSTER);
		final String label = labels.get(id);
		if (id < 1 || label == null)
		{
			return;
		}
		final CaCompletion.Shade shade = CaCompletion.shadeOf(id, autoDetect, almostDone, completeMonsters, markNow,
			progressNow);
		int matched = colourChosenTree(client.getWidget(InterfaceID.CaTasks.MONSTER_FILTER), 0, label, shade);
		matched += colourChosenTree(client.getWidget(InterfaceID.CaTasks.DROPDOWN_BOX), 0, label, shade);
		if (!boxLogged && matched > 0)
		{
			boxLogged = true;
			log.debug("Chosen-name boxes matched {} widgets", matched);
		}
	}

	/** Colours the widget and its children down to depth 3 that show {@code label}; returns how many matched. */
	private int colourChosenTree(Widget widget, int depth, String label, CaCompletion.Shade shade)
	{
		if (widget == null || widget.isHidden())
		{
			return 0;
		}
		int matched = 0;
		if (CaCompletion.showsLabel(widget.getText(), label))
		{
			matched++;
			final long key = ((long) widget.getId() << 16) | (widget.getIndex() & 0xFFFF);
			if (shade == CaCompletion.Shade.PLAIN)
			{
				final Integer original = originalColours.get(key);
				if (original != null && widget.getTextColor() != original)
				{
					widget.setTextColor(original);
				}
			}
			else
			{
				originalColours.putIfAbsent(key, widget.getTextColor());
				widget.setTextColor(colourOf(shade));
			}
		}
		if (depth < 3)
		{
			matched += colourAll(widget.getStaticChildren(), depth + 1, label, shade);
			matched += colourAll(widget.getDynamicChildren(), depth + 1, label, shade);
			matched += colourAll(widget.getNestedChildren(), depth + 1, label, shade);
		}
		return matched;
	}

	private int colourAll(Widget[] children, int depth, String label, CaCompletion.Shade shade)
	{
		int matched = 0;
		if (children != null)
		{
			for (Widget child : children)
			{
				matched += colourChosenTree(child, depth, label, shade);
			}
		}
		return matched;
	}
}

package com.cabosschecklist;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The game's Combat Achievement completion rules, with no RuneLite types so they are tested without a client. Each rule
 * names the game script it copies (Joshua-F/osrs-dumps 44e1ff8).
 */
final class CaCompletion
{
	private CaCompletion()
	{
	}

	/** One Combat Achievement task, with the four params the rules read. */
	static final class Task
	{
		final int taskId;
		final int monsterId;
		final int gimMaxGroupSize;
		final int deadmanFlag;

		Task(int taskId, int monsterId, int gimMaxGroupSize, int deadmanFlag)
		{
			this.taskId = taskId;
			this.monsterId = monsterId;
			this.gimMaxGroupSize = gimMaxGroupSize;
			this.deadmanFlag = deadmanFlag;
		}
	}

	/** Whether the task's bit is set: 32 tasks to a varp (proc script4834). */
	static boolean isTaskDone(int taskId, int[] completedVarps)
	{
		if (taskId < 0 || taskId / 32 >= completedVarps.length)
		{
			return false;
		}
		return ((completedVarps[taskId / 32] >>> (taskId % 32)) & 1) == 1;
	}

	/** Whether the game leaves the task out of the count (proc ca_task_is_disabled, 5243). */
	static boolean isSkipped(Task task, boolean deadmanWorld, int gimGroupSize)
	{
		if (deadmanWorld)
		{
			return task.deadmanFlag == 1;
		}
		if (gimGroupSize < 2 || gimGroupSize > 5)
		{
			return false;
		}
		return gimGroupSize <= task.gimMaxGroupSize;
	}

	/** One monster's counted tasks and how many of them are done. */
	static final class Progress
	{
		final int total;
		final int done;

		Progress(int total, int done)
		{
			this.total = total;
			this.done = done;
		}

		/** Whether the monster has counted tasks and all are done. */
		boolean complete()
		{
			return total > 0 && done == total;
		}
	}

	/**
	 * Each monster that has a task in the list, with the count of its tasks the game does not skip and how many of those
	 * are done (proc ca_bosses_draw_list, 4800).
	 */
	static Map<Integer, Progress> progress(List<Task> tasks, int[] completedVarps, boolean deadmanWorld, int gimGroupSize)
	{
		final Map<Integer, int[]> counts = new HashMap<>();
		for (Task task : tasks)
		{
			final int[] count = counts.computeIfAbsent(task.monsterId, k -> new int[2]);
			if (isSkipped(task, deadmanWorld, gimGroupSize))
			{
				continue;
			}
			count[0]++;
			if (isTaskDone(task.taskId, completedVarps))
			{
				count[1]++;
			}
		}
		final Map<Integer, Progress> result = new HashMap<>();
		for (Map.Entry<Integer, int[]> entry : counts.entrySet())
		{
			result.put(entry.getKey(), new Progress(entry.getValue()[0], entry.getValue()[1]));
		}
		return result;
	}

	/** One task's words from the game's task struct: name, description, tier number (1 to 6) and type number (1 to 6). */
	static final class TaskText
	{
		final String name;
		final String description;
		final int tier;
		final int type;

		TaskText(String name, String description, int tier, int type)
		{
			this.name = name;
			this.description = description;
			this.tier = tier;
			this.type = type;
		}
	}

	/** One row of a boss's task list: the task's words, its tier and type in words, and whether the account did it. */
	static final class TaskLine
	{
		final int taskId;
		final String name;
		final String description;
		final String tier;
		final String type;
		final boolean done;

		TaskLine(int taskId, String name, String description, String tier, String type, boolean done)
		{
			this.taskId = taskId;
			this.name = name;
			this.description = description;
			this.tier = tier;
			this.type = type;
			this.done = done;
		}

		/** The row's second line: the tier word, a dot, the type word. */
		String detail()
		{
			return tier + " \u00b7 " + type;
		}
	}

	/** A task's tier number and line, kept together while a monster's lines are sorted. */
	private static final class Sortable
	{
		final int tier;
		final TaskLine line;

		Sortable(int tier, TaskLine line)
		{
			this.tier = tier;
			this.line = line;
		}
	}

	/**
	 * Each monster's counted tasks (the ones {@link #isSkipped} leaves in) as rows, ordered by tier number, then name
	 * ignoring case, then task id. A task with no text gets an empty name and description; a missing tier or type word is
	 * "". Tabs in the texts become spaces. Choice: a monster whose tasks are all skipped is in the map with an empty list.
	 */
	static Map<Integer, List<TaskLine>> taskLines(List<Task> tasks, Map<Integer, TaskText> texts,
		Map<Integer, String> tierWords, Map<Integer, String> typeWords, int[] completedVarps, boolean deadmanWorld,
		int gimGroupSize)
	{
		final Map<Integer, List<Sortable>> byMonster = new HashMap<>();
		for (Task task : tasks)
		{
			final List<Sortable> list = byMonster.computeIfAbsent(task.monsterId, k -> new ArrayList<>());
			if (isSkipped(task, deadmanWorld, gimGroupSize))
			{
				continue;
			}
			final TaskText text = texts.get(task.taskId);
			final String name = text == null ? "" : spaced(text.name);
			final String description = text == null ? "" : spaced(text.description);
			final int tier = text == null ? 0 : text.tier;
			final String tierWord = text == null ? null : tierWords.get(text.tier);
			final String typeWord = text == null ? null : typeWords.get(text.type);
			list.add(new Sortable(tier, new TaskLine(task.taskId, name, description, tierWord == null ? "" : tierWord,
				typeWord == null ? "" : typeWord, isTaskDone(task.taskId, completedVarps))));
		}
		final Map<Integer, List<TaskLine>> result = new HashMap<>();
		for (Map.Entry<Integer, List<Sortable>> entry : byMonster.entrySet())
		{
			final List<Sortable> sorted = entry.getValue();
			sorted.sort((a, b) ->
			{
				if (a.tier != b.tier)
				{
					return Integer.compare(a.tier, b.tier);
				}
				final int byName = String.CASE_INSENSITIVE_ORDER.compare(a.line.name, b.line.name);
				return byName != 0 ? byName : Integer.compare(a.line.taskId, b.line.taskId);
			});
			final List<TaskLine> lines = new ArrayList<>();
			for (Sortable item : sorted)
			{
				lines.add(item.line);
			}
			result.put(entry.getKey(), Collections.unmodifiableList(lines));
		}
		return result;
	}

	private static String spaced(String text)
	{
		return text == null ? "" : text.replace('\t', ' ');
	}

	/** Whether the monster has done at least one counted task and has one or two left. */
	static boolean isAlmostDone(Progress progress)
	{
		if (progress == null)
		{
			return false;
		}
		final int left = progress.total - progress.done;
		return progress.done >= 1 && (left == 1 || left == 2);
	}

	/**
	 * The monsters whose counted tasks are all done and number more than none (proc ca_bosses_draw_list, 4800, which
	 * colours a Bosses-tab name green).
	 */
	static Set<Integer> completeIds(Map<Integer, Progress> progress)
	{
		final Set<Integer> complete = new HashSet<>();
		for (Map.Entry<Integer, Progress> entry : progress.entrySet())
		{
			if (entry.getValue().complete())
			{
				complete.add(entry.getKey());
			}
		}
		return complete;
	}

	/** How a monster's name is drawn: the game's own colour, green, or yellow. */
	enum Shade
	{
		PLAIN, GREEN, YELLOW
	}

	/**
	 * The shade of a monster's name: green when {@link Marks#isGreen}; else yellow when {@code almostDone} is on and the
	 * monster's progress is almost done; else plain. Id 0 ("All") and below are always plain; {@code progress} may be null.
	 */
	static Shade shadeOf(int id, boolean autoDetect, boolean almostDone, Set<Integer> complete, Map<Integer, Mark> marks,
		Map<Integer, Progress> progress)
	{
		if (id < 1)
		{
			return Shade.PLAIN;
		}
		if (Marks.isGreen(id, autoDetect, complete, marks))
		{
			return Shade.GREEN;
		}
		if (almostDone && progress != null && isAlmostDone(progress.get(id)))
		{
			return Shade.YELLOW;
		}
		return Shade.PLAIN;
	}

	/**
	 * Whether a box's text shows {@code label}: the label itself, or the label cut short with "..." (the game's
	 * ca_task_filter_updatetext cuts it to the box's width). A blank text, or a lone "...", never does.
	 */
	static boolean showsLabel(String text, String label)
	{
		if (text == null || label == null || text.trim().isEmpty())
		{
			return false;
		}
		if (text.equals(label))
		{
			return true;
		}
		if (text.endsWith("...") && text.length() > 3)
		{
			final String start = text.substring(0, text.length() - 3).trim();
			return !start.isEmpty() && label.startsWith(start);
		}
		return false;
	}

	/**
	 * The entry id of a dropdown row (clientscript ca_task_filter_open, 4826): child 0 is the hover box and the entry for
	 * key k is child k + 1; sorting moves rows on screen and never changes an index.
	 */
	static int idForRow(int childIndex)
	{
		return childIndex >= 1 ? childIndex - 1 : -1;
	}

	/** The sidebar card's bold line. */
	static String statusHeadline(int done, int total)
	{
		return done + " of " + total + " done";
	}
}

package com.cabosschecklist;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * What the sidebar shows, built from immutable inputs on any thread, with no RuneLite or Swing types: the panel only
 * draws it.
 */
final class ChecklistView
{
	/** One boss of the game's Monster list, with its progress, its mark and whether it shows green. */
	static final class Boss
	{
		final int id;
		final String label;
		/** The game's long name for the boss (enum 3971), or the label when the game has none. */
		final String name;
		final int total;
		final int done;
		/** Null when the boss has no mark. */
		final Mark mark;
		final boolean green;
		/** The colour of the boss's name in the game's Monster list. */
		final CaCompletion.Shade shade;
		/** The colour the boss would have now without its mark. */
		final CaCompletion.Shade unmarkedShade;
		/** Null when the boss has no mark. */
		final Marks.Group group;

		Boss(int id, String label, String name, int total, int done, Mark mark, boolean green, CaCompletion.Shade shade,
			CaCompletion.Shade unmarkedShade, Marks.Group group)
		{
			this.id = id;
			this.label = label;
			this.name = name;
			this.total = total;
			this.done = done;
			this.mark = mark;
			this.green = green;
			this.shade = shade;
			this.unmarkedShade = unmarkedShade;
			this.group = group;
		}

		/**
		 * Whether the boss stays in the list for the search text: a blank or null query matches every boss, else the
		 * label or the name must contain the trimmed text, ignoring case.
		 */
		boolean matches(String query)
		{
			if (query == null || query.trim().isEmpty())
			{
				return true;
			}
			final String wanted = query.trim().toLowerCase(Locale.ROOT);
			return label.toLowerCase(Locale.ROOT).contains(wanted) || name.toLowerCase(Locale.ROOT).contains(wanted);
		}

		/** The card's progress line. */
		String progressLine()
		{
			if (total == 0)
			{
				return "No tasks yet";
			}
			return done + " of " + total + (total == 1 ? " task" : " tasks") + " done";
		}

		/** The word at the right of a Bosses row. */
		String status()
		{
			if (mark != null)
			{
				return "Marked";
			}
			if (total == 0)
			{
				return "No tasks";
			}
			return done == total ? "Done" : (total - done) + " left";
		}

		/** The account's progress in a Manual row: "done of total done", or "no tasks yet" for a boss with none. */
		String accountText()
		{
			return total == 0 ? "no tasks yet" : done + " of " + total + " done";
		}

		/** Whether the mark changes the colour the game shows: the shade differs from the unmarked one. */
		boolean overrides()
		{
			return shade != unmarkedShade;
		}

		/** The colour the game shows now, as a capitalised word. */
		String shownWord()
		{
			return word(shade, true);
		}

		/** The colour the boss would show without its mark, in lower case. */
		String unmarkedWord()
		{
			return word(unmarkedShade, false);
		}

		private static String word(CaCompletion.Shade shade, boolean capital)
		{
			final String word = shade == CaCompletion.Shade.GREEN ? "green"
				: shade == CaCompletion.Shade.YELLOW ? "yellow" : "orange";
			return capital ? Character.toUpperCase(word.charAt(0)) + word.substring(1) : word;
		}

		/** The tooltip of the account's progress in a Manual row. */
		String accountLine()
		{
			if (total == 0)
			{
				return "Your account: no tasks yet";
			}
			final int left = total - done;
			if (left == 0)
			{
				return "Your account: all tasks done";
			}
			return "Your account: " + (left == 1 ? "1 task left" : left + " tasks left");
		}
	}

	/** The bosses in row order: by label ignoring case, then id. */
	final List<Boss> bosses;
	final boolean autoDetect;
	final int greenCount;
	final int markCount;
	/** Each boss's task rows by boss id; empty from {@link #build}. */
	final Map<Integer, List<CaCompletion.TaskLine>> tasks;
	/** The overriding marks the player has looked at in the Manual tab. */
	final Map<Integer, Mark> seen;

	private ChecklistView(List<Boss> bosses, boolean autoDetect, int greenCount, int markCount,
		Map<Integer, List<CaCompletion.TaskLine>> tasks, Map<Integer, Mark> seen)
	{
		this.bosses = Collections.unmodifiableList(bosses);
		this.autoDetect = autoDetect;
		this.greenCount = greenCount;
		this.markCount = markCount;
		this.tasks = tasks;
		this.seen = seen;
	}

	/**
	 * One boss per entry of {@code labels}; marks for ids not in {@code labels} are ignored everywhere. {@code names} are
	 * the game's long names; a boss with none (or a blank one) takes its label for its name. {@code almostDone} lets a boss
	 * with one or two tasks left take the yellow shade. {@code seen} are the overriding marks the player has looked at.
	 */
	static ChecklistView build(Map<Integer, String> labels, Map<Integer, String> names,
		Map<Integer, CaCompletion.Progress> progress, Map<Integer, Mark> marks, boolean autoDetect, boolean almostDone,
		Map<Integer, Mark> seen)
	{
		final Set<Integer> complete = CaCompletion.completeIds(progress);
		final List<Integer> ids = new ArrayList<>(labels.keySet());
		ids.sort((a, b) ->
		{
			final int byLabel = String.CASE_INSENSITIVE_ORDER.compare(labels.get(a), labels.get(b));
			return byLabel != 0 ? byLabel : Integer.compare(a, b);
		});
		final List<Boss> bosses = new ArrayList<>();
		int greens = 0;
		int marked = 0;
		for (int id : ids)
		{
			final CaCompletion.Progress counts = progress.get(id);
			final int total = counts == null ? 0 : counts.total;
			final int done = counts == null ? 0 : counts.done;
			final Mark mark = marks.get(id);
			final Marks.Group group = mark == null ? null : Marks.groupOf(mark, total, done);
			final boolean green = Marks.isGreen(id, autoDetect, complete, marks);
			final String longName = names.get(id);
			final String name = longName == null || longName.trim().isEmpty() ? labels.get(id) : longName;
			final CaCompletion.Shade shade = CaCompletion.shadeOf(id, autoDetect, almostDone, complete, marks, progress);
			final CaCompletion.Shade unmarkedShade = CaCompletion.shadeOf(id, autoDetect, almostDone, complete,
				Collections.emptyMap(), progress);
			bosses.add(new Boss(id, labels.get(id), name, total, done, mark, green, shade, unmarkedShade, group));
			greens += green ? 1 : 0;
			marked += mark == null ? 0 : 1;
		}
		return new ChecklistView(bosses, autoDetect, greens, marked, Collections.emptyMap(),
			Collections.unmodifiableMap(new HashMap<>(seen)));
	}

	/** A copy of this view that holds {@code lines} as the bosses' task rows. */
	ChecklistView withTasks(Map<Integer, List<CaCompletion.TaskLine>> lines)
	{
		return new ChecklistView(bosses, autoDetect, greenCount, markCount, lines, seen);
	}

	/** The boss's task rows in list order; empty when it has none. */
	List<CaCompletion.TaskLine> tasksOf(int id)
	{
		final List<CaCompletion.TaskLine> lines = tasks.get(id);
		return lines == null ? Collections.emptyList() : lines;
	}

	/** What the boss card says under its box: a tag, some words, both or nothing. */
	enum CardNote
	{
		NONE(false, false, ""),
		HINT(false, false, "Tick to show it green"),
		OVERRIDES(true, true, "overrides your progress"),
		SAME(true, false, "same as your progress"),
		MARK(true, false, "");

		/** Whether the tag (see {@link MarkTag#TEXT}) shows. */
		final boolean tag;
		/** Whether the tag is drawn strong, in orange (the mark overrides), rather than in grey. */
		final boolean strong;
		/** The words after the tag; empty for none. */
		final String text;

		CardNote(boolean tag, boolean strong, String text)
		{
			this.tag = tag;
			this.strong = strong;
			this.text = text;
		}
	}

	/** What the card says about {@code boss}: nothing for an unmarked boss while the account is followed. */
	CardNote cardNote(Boss boss)
	{
		if (boss.mark == null)
		{
			return autoDetect ? CardNote.NONE : CardNote.HINT;
		}
		if (!autoDetect)
		{
			return CardNote.MARK;
		}
		return boss.group == Marks.Group.DIFFERENT ? CardNote.OVERRIDES : CardNote.SAME;
	}

	/** The status card's bold line. */
	String headline()
	{
		return CaCompletion.statusHeadline(greenCount, bosses.size());
	}

	/** The status card's grey line: it never changes with the marks. */
	String helper()
	{
		return autoDetect ? "Shown green in the Tasks menu" : "Only marked bosses show green";
	}

	/** The toggle's second word. */
	String manualWord()
	{
		return markCount == 0 ? "Manual" : "Manual (" + markCount + ")";
	}

	/** The marks of the group DIFFERENT by boss id while the account is followed; none otherwise. */
	Map<Integer, Mark> overriding()
	{
		final Map<Integer, Mark> result = new HashMap<>();
		if (autoDetect)
		{
			for (Boss boss : group(Marks.Group.DIFFERENT))
			{
				result.put(boss.id, boss.mark);
			}
		}
		return Collections.unmodifiableMap(result);
	}

	/** Whether some overriding mark has not been seen yet. */
	boolean unseen()
	{
		return autoDetect && Marks.hasUnseen(seen, overriding());
	}

	/** The seen marks after the player has ({@code looking}) or has not looked at the Manual tab. */
	Map<Integer, Mark> seenAfter(boolean looking)
	{
		return autoDetect ? Marks.seenAfter(seen, overriding(), looking) : seen;
	}

	/** The marked bosses in {@code group}, in row order. */
	List<Boss> group(Marks.Group group)
	{
		final List<Boss> result = new ArrayList<>();
		for (Boss boss : bosses)
		{
			if (boss.group == group)
			{
				result.add(boss);
			}
		}
		return result;
	}

	/** Every marked boss, in row order. */
	List<Boss> marked()
	{
		final List<Boss> result = new ArrayList<>();
		for (Boss boss : bosses)
		{
			if (boss.mark != null)
			{
				result.add(boss);
			}
		}
		return result;
	}
}

package com.cabosschecklist;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;

/**
 * The 2hBuilds coin, the family mark every 2hBuilds plugin carries in the top-left corner of its sidebar icon: a
 * hammered gold disc 9 px across with its "2h" struck in dark brown, drawn in code so it needs no image file. It is
 * the coin half of {@link NavIcon}, pulled out so the one picture can be copied into another plugin's package
 * unchanged - it refers to nothing of this plugin's and to no class but the JDK's.
 *
 * <p>{@link #paint} draws it where it sits in a 16 x 16 icon, the disc centred on (4.5, 4.5): three jittered discs
 * with antialiasing on, then the two letters crisp on top, antialiasing off again, so a caller that draws more on
 * the same {@link Graphics2D} afterwards gets the hint it had not set itself.
 */
final class CoinGlyph
{
	private static final Color RIM = new Color(88, 62, 16);
	private static final Color EDGE = new Color(140, 102, 30);
	private static final Color FACE = new Color(196, 156, 58);
	private static final Color INK = new Color(52, 36, 8);

	/** The coin's centre and the three radii of its rim, edge and face. */
	private static final double COIN_X = 4.5, COIN_Y = 4.5;
	private static final double[] RADII = {4.7, 3.9, 3.3};
	private static final Color[] RINGS = {RIM, EDGE, FACE};
	/** The hammering: one offset per sixteenth of the edge. */
	private static final double[] JITTER = {0.3, -0.2, 0.4, 0.1, -0.3, 0.2, 0.4, -0.1, 0.2, -0.4, 0.3, 0.0, -0.3, 0.4, -0.1, 0.2};

	/** The letters, one character a pixel: "2" then "h", 3 wide and 5 tall each, a 1 px gap between. */
	private static final String[] TWO = {"###", "..#", "###", "#..", "###"};
	private static final String[] H = {"#..", "#..", "###", "#.#", "#.#"};
	private static final int LETTERS_X = 1, LETTERS_Y = 2;

	private CoinGlyph()
	{
	}

	/**
	 * Draws the coin in the top-left of the 16 x 16 icon {@code g} paints on: three jittered discs with
	 * antialiasing, then the letters crisp on top. Leaves the antialiasing hint off and the colour at the letters'
	 * ink.
	 */
	static void paint(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (int i = 0; i < RADII.length; i++)
		{
			g.setColor(RINGS[i]);
			g.fill(coin(RADII[i]));
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		glyph(g, TWO, LETTERS_X, LETTERS_Y);
		glyph(g, H, LETTERS_X + 4, LETTERS_Y);
	}

	private static Path2D coin(double radius)
	{
		final Path2D path = new Path2D.Double();
		for (int i = 0; i < JITTER.length; i++)
		{
			final double angle = i * Math.PI * 2 / JITTER.length;
			final double r = radius + JITTER[i];
			final double x = COIN_X + Math.cos(angle) * r;
			final double y = COIN_Y + Math.sin(angle) * r;
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}
		path.closePath();
		return path;
	}

	private static void glyph(Graphics2D g, String[] rows, int x, int y)
	{
		g.setColor(INK);
		for (int r = 0; r < rows.length; r++)
		{
			for (int c = 0; c < rows[r].length(); c++)
			{
				if (rows[r].charAt(c) == '#')
				{
					g.fillRect(x + c, y + r, 1, 1);
				}
			}
		}
	}
}

package com.cabosschecklist;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.DefaultFocusTraversalPolicy;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics2D;
import java.awt.GraphicsEnvironment;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.Window;
import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.AbstractAction;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.KeyStroke;
import javax.swing.WindowConstants;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * A small question window over the client, with a yes button and <i>Cancel</i>, in RuneLite's dark colours. The yes
 * button is the default button and takes the focus, so Enter answers yes; Escape, <i>Cancel</i> and the window's close
 * box all answer no. It is modal to the client window that owns it. Modelled on the bank plugin's question window.
 *
 * <p>The panel of controls ({@link #content}) is built without a window, so a test can press its buttons on a machine
 * with no screen; the {@link JDialog} that hosts it is made only by {@link #window}.
 */
final class ConfirmDialog
{
	static final String CANCEL_TEXT = "Cancel";

	private static final int PAD_TOP = 14;
	private static final int PAD_SIDE = 18;
	private static final int PAD_BOTTOM = 12;
	/** The tile holding the doubled picture, in px, and the picture's scale. */
	private static final int TILE = 42;
	private static final int SCALE = 2;
	/** The gap between the tile and the lines, and under the first line, between the middle lines, above the last. */
	private static final int TILE_GAP = 14;
	private static final int AFTER_FIRST = 6;
	private static final int BETWEEN = 3;
	private static final int BEFORE_LAST = 8;
	private static final int BUTTON_GAP = 6;
	private static final int BUTTONS_TOP = 14;
	private static final Color MIDDLE_GRAY = new Color(0xD6D6D6);
	/** The key Escape is bound under in {@link #content}'s action map. */
	static final String CANCEL_KEY = "cancel";

	/** Everything the window shows, built without a window. */
	final JPanel content = new JPanel(new BorderLayout());
	/** One label per line of the question, in order. */
	final List<JLabel> lines;
	/** The label holding the doubled picture; null when there is no picture. */
	final JLabel pictureLabel;
	final JButton yesButton;
	final JButton cancelButton;
	/** True once the yes button was pressed; false until then, whatever else closes the window. EDT. */
	boolean answeredYes;
	/** The hosting dialog; null until {@link #window}, and again once closed. EDT. */
	private JDialog dialog;

	/**
	 * Builds the controls: the {@code picture} (the sidebar button's icon, or null for none) drawn at twice its size in
	 * a tile at the left, then one label per line of {@code question}, then the buttons. Choice: the tile is a
	 * 42 x 42 panel with a 1 px border at the top of the row, so it is level with the first line; with two lines
	 * the second is a middle line, and a single line is the bold first line.
	 */
	ConfirmDialog(BufferedImage picture, String question, String yes)
	{
		content.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		content.setBorder(new EmptyBorder(PAD_TOP, PAD_SIDE, PAD_BOTTOM, PAD_SIDE));

		final String[] parts = question.split("\n");
		final List<JLabel> made = new ArrayList<>();
		final JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setOpaque(false);
		for (int i = 0; i < parts.length; i++)
		{
			final boolean first = i == 0;
			final boolean last = i == parts.length - 1 && parts.length >= 3;
			final JLabel label = new JLabel(parts[i]);
			label.setFont(first ? ViewParts.bold(12f) : ViewParts.plain(12f));
			label.setForeground(first ? Color.WHITE : last ? ColorScheme.LIGHT_GRAY_COLOR : MIDDLE_GRAY);
			label.setAlignmentX(Component.LEFT_ALIGNMENT);
			if (i > 0)
			{
				text.add(Box.createVerticalStrut(i == 1 ? AFTER_FIRST : last ? BEFORE_LAST : BETWEEN));
			}
			text.add(label);
			made.add(label);
		}
		lines = Collections.unmodifiableList(made);

		final JPanel row = new JPanel(new BorderLayout(TILE_GAP, 0));
		row.setOpaque(false);
		if (picture == null)
		{
			pictureLabel = null;
		}
		else
		{
			pictureLabel = new JLabel(new ImageIcon(doubled(picture)));
			final JPanel tile = new JPanel(new GridBagLayout());
			tile.setBackground(ColorScheme.DARK_GRAY_COLOR);
			tile.setBorder(new LineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 1));
			tile.setPreferredSize(new Dimension(TILE, TILE));
			tile.add(pictureLabel);
			final JPanel top = new JPanel(new BorderLayout());
			top.setOpaque(false);
			top.add(tile, BorderLayout.NORTH);
			row.add(top, BorderLayout.WEST);
		}
		row.add(text, BorderLayout.CENTER);
		content.add(row, BorderLayout.CENTER);

		yesButton = smallButton(yes, true);
		cancelButton = smallButton(CANCEL_TEXT, false);
		final JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, BUTTON_GAP, 0));
		buttons.setOpaque(false);
		buttons.setBorder(new EmptyBorder(BUTTONS_TOP, 0, 0, 0));
		buttons.add(yesButton);
		buttons.add(cancelButton);
		content.add(buttons, BorderLayout.SOUTH);

		// Escape is Cancel wherever the focus is in the window.
		content.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW)
			.put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), CANCEL_KEY);
		content.getActionMap().put(CANCEL_KEY, new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				answer(false);
			}
		});
	}

	/** A new image of {@code picture} at twice its size, drawn with nearest-neighbour scaling so it stays sharp. */
	private static BufferedImage doubled(BufferedImage picture)
	{
		final BufferedImage out = new BufferedImage(picture.getWidth() * SCALE, picture.getHeight() * SCALE,
			BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = out.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			g.drawImage(picture, 0, 0, out.getWidth(), out.getHeight(), null);
		}
		finally
		{
			g.dispose();
		}
		return out;
	}

	private JButton smallButton(String text, boolean yes)
	{
		final JButton button = new JButton(text);
		button.setFont(ViewParts.plain(12f));
		button.setFocusPainted(false);
		button.setMargin(new Insets(1, 5, 1, 5));
		button.addActionListener(e -> answer(yes));
		return button;
	}

	/**
	 * EDT. Puts the question to the player and answers what they chose: true for the yes button only. Blocks - the
	 * dialog is modal - until it is closed. Answers false at once on a machine with no display.
	 *
	 * @param owner the RuneLite frame (the panel's window ancestor), or null
	 * @param picture the picture drawn at twice its size at the left, or null for none
	 * @param title the window's title
	 * @param yes the word on the button that answers yes
	 */
	static boolean ask(Window owner, BufferedImage picture, String title, String question, String yes)
	{
		if (GraphicsEnvironment.isHeadless())
		{
			return false;
		}
		final ConfirmDialog window = window(owner, picture, title, question, yes);
		window.dialog.setVisible(true);
		return window.answeredYes;
	}

	/**
	 * The window built and sized but not yet shown: a {@link JDialog} owned by {@code owner}, modal to its owner's
	 * windows, closing by disposing, with the yes button as its default button and the first focus, not resizable,
	 * centred on the owner. Needs a display.
	 */
	static ConfirmDialog window(Window owner, BufferedImage picture, String title, String question, String yes)
	{
		final ConfirmDialog window = new ConfirmDialog(picture, question, yes);
		final JDialog dialog = new JDialog(owner, title);
		dialog.setModalityType(Dialog.ModalityType.DOCUMENT_MODAL);
		dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
		dialog.setContentPane(window.content);
		dialog.getRootPane().setDefaultButton(window.yesButton);
		dialog.setResizable(false);
		dialog.pack();
		dialog.setLocationRelativeTo(owner);
		dialog.setFocusTraversalPolicy(new DefaultFocusTraversalPolicy()
		{
			@Override
			public Component getInitialComponent(Window w)
			{
				return window.yesButton;
			}
		});
		window.dialog = dialog;
		return window;
	}

	/** A button's press, or Escape: remembers the answer and closes the window; harmless with no window. */
	private void answer(boolean yes)
	{
		answeredYes = yes;
		final JDialog host = dialog;
		dialog = null;
		if (host != null)
		{
			host.dispose();
		}
	}
}

package com.cabosschecklist;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The 2hBuilds settings icon, drawn in code: a ring with eight teeth and a hole through the middle, the picture the
 * settings icon of every 2hBuilds plugin shows (STANDARD A4). It is the bank's icon, pulled out of its widget helper so
 * the one picture can be copied into another plugin unchanged; it refers to no class of the plugin it sits in.
 *
 * <p>The ring is a stroke and not a filled disc, so the middle stays transparent and the picture reads as a settings
 * icon at 12 px rather than as a cogged blob. The teeth are eight round-capped spokes every 45 degrees, starting on
 * the ring's own circle so each is rooted in the ring's metal and none reaches into the hole. Every length is a
 * fraction of the size, so the same shape comes out at any size.
 */
final class GearGlyph
{
	/** The number of teeth. */
	static final int TEETH = 8;
	/** The smallest side drawn: below it the hole closes and the teeth merge. */
	static final int MIN_SIZE = 7;

	private GearGlyph()
	{
	}

	/**
	 * A new square icon, transparent except for the ring and its teeth.
	 *
	 * @param size   the icon's side in px; anything under {@value #MIN_SIZE} is raised to it
	 * @param colour the ink; null falls back to the sidebar's quiet grey, {@link ColorScheme#LIGHT_GRAY_COLOR}
	 */
	static ImageIcon icon(int size, Color colour)
	{
		final int s = Math.max(MIN_SIZE, size);
		final BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(colour == null ? ColorScheme.LIGHT_GRAY_COLOR : colour);
			final double centre = s / 2.0;
			// The ring's centre line, the width of its metal, and how far a tooth's centre line reaches - the last
			// one pulled in by half a tooth so the round cap lands inside the icon instead of being clipped.
			final double ring = centre * 0.52;
			final float ringWidth = (float) Math.max(1.5, s * 0.2);
			final float toothWidth = (float) Math.max(1.3, s * 0.16);
			final double toothOut = centre - toothWidth / 2.0 - 0.25;
			g.setStroke(new BasicStroke(ringWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(centre - ring, centre - ring, ring * 2.0, ring * 2.0));
			g.setStroke(new BasicStroke(toothWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < TEETH; i++)
			{
				final double angle = i * 2.0 * Math.PI / TEETH;
				final double cos = Math.cos(angle);
				final double sin = Math.sin(angle);
				g.draw(new Line2D.Double(centre + cos * ring, centre + sin * ring,
					centre + cos * toothOut, centre + sin * toothOut));
			}
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(img);
	}
}

package com.cabosschecklist;

import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.util.function.IntConsumer;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Two halves side by side in one bordered box, the lit half orange with its word in dark bold and the other dark with
 * its word in grey: the bank's toggle. The halves are equal and both words take one size, the largest up to 12 at which
 * each keeps {@link #TOGGLE_AIR} px a side. The box fills the width it is given.
 */
final class HalfToggle extends JPanel
{
	/** The toggle's height, in px, its 1 px border included. */
	static final int TOGGLE_HEIGHT = 20;
	/** The least air, in px, left and right of a half's word. */
	static final int TOGGLE_AIR = 2;
	/** The largest size, in px, the words are set in. */
	static final int TOGGLE_TEXT_MAX = 12;
	/** The smallest size, so a box far narrower than the sidebar still ends. */
	private static final int TOGGLE_TEXT_MIN = 6;

	/** The side of the dot, in px. */
	private static final int DOT_SIZE = 7;
	/** The space between a half's word and its dot, in px. */
	private static final int DOT_GAP = 5;
	/** The dot: a filled orange circle, one shared icon. */
	private static final Icon DOT = new Icon()
	{
		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			final Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(ColorScheme.BRAND_ORANGE);
			g2.fill(new Ellipse2D.Float(x, y, DOT_SIZE, DOT_SIZE));
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return DOT_SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return DOT_SIZE;
		}
	};

	private final JLabel[] halves = new JLabel[2];
	/** Which half is lit: 0, 1, or -1 before the caller first says. */
	private int lit = -1;
	private int textSize = TOGGLE_TEXT_MAX;
	private Font litFont = bold(TOGGLE_TEXT_MAX);
	private Font unlitFont = plain(TOGGLE_TEXT_MAX);

	/** @param onPress called with the index of an unlit half that is pressed */
	HalfToggle(String first, String second, IntConsumer onPress)
	{
		super(null);
		setBorder(new MatteBorder(1, 1, 1, 1, ColorScheme.MEDIUM_GRAY_COLOR));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		final String[] words = {first, second};
		for (int i = 0; i < halves.length; i++)
		{
			final int index = i;
			final JLabel half = new JLabel(words[i]);
			half.setHorizontalAlignment(SwingConstants.CENTER);
			half.setVerticalAlignment(SwingConstants.CENTER);
			half.setOpaque(true);
			half.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (isPress(e) && !isLit(index))
					{
						onPress.accept(index);
					}
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					if (!isLit(index))
					{
						half.setForeground(ColorScheme.BRAND_ORANGE);
					}
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					paintHalf(index);
				}
			});
			halves[i] = half;
			add(half);
		}
		setPreferredSize(new Dimension(1, TOGGLE_HEIGHT));
		setMinimumSize(new Dimension(1, TOGGLE_HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, TOGGLE_HEIGHT));
		setLit(0);
	}

	private static Font plain(int size)
	{
		return FontManager.getDefaultFont().deriveFont((float) size);
	}

	private static Font bold(int size)
	{
		return FontManager.getDefaultBoldFont().deriveFont((float) size);
	}

	/** Lights half {@code index} (0 or 1) and unlights the other; the same half again repaints nothing. */
	void setLit(int index)
	{
		final int want = index == 1 ? 1 : 0;
		if (want == lit)
		{
			return;
		}
		lit = want;
		for (int i = 0; i < halves.length; i++)
		{
			paintHalf(i);
		}
	}

	/** Sets half {@code index}'s word and fits both words again. */
	void setWord(int index, String word)
	{
		halves[index].setText(word);
		revalidate();
		repaint();
	}

	/**
	 * Puts the dot after half {@code index}'s word and sets the half's tooltip to {@code tip}; a null {@code tip}
	 * removes both. Fits the words again.
	 */
	void setDot(int index, String tip)
	{
		final JLabel half = halves[index];
		half.setIcon(tip == null ? null : DOT);
		half.setHorizontalTextPosition(SwingConstants.LEADING);
		half.setIconTextGap(DOT_GAP);
		half.setToolTipText(tip);
		revalidate();
		repaint();
	}

	/**
	 * The halves are equal (the second takes the odd pixel) and both words are set in one size: the largest whole size up
	 * to {@link #TOGGLE_TEXT_MAX} at which each word, in the wider of the bold and plain faces, fits its half with
	 * {@link #TOGGLE_AIR} px on each side.
	 */
	@Override
	public void doLayout()
	{
		final Insets in = getInsets();
		final int inner = getWidth() - in.left - in.right;
		final int height = getHeight() - in.top - in.bottom;
		final int first = inner / 2;
		final int[] widths = {first, inner - first};
		int size = TOGGLE_TEXT_MAX;
		while (size > TOGGLE_TEXT_MIN && !fits(size, widths))
		{
			size--;
		}
		if (size != textSize)
		{
			textSize = size;
			litFont = bold(size);
			unlitFont = plain(size);
			for (int i = 0; i < halves.length; i++)
			{
				paintHalf(i);
			}
		}
		halves[0].setBounds(in.left, in.top, widths[0], height);
		halves[1].setBounds(in.left + widths[0], in.top, widths[1], height);
	}

	private boolean fits(int size, int[] widths)
	{
		final FontMetrics boldMetrics = getFontMetrics(bold(size));
		final FontMetrics plainMetrics = getFontMetrics(plain(size));
		for (int i = 0; i < halves.length; i++)
		{
			final String word = halves[i].getText();
			final int text = Math.max(boldMetrics.stringWidth(word), plainMetrics.stringWidth(word));
			final int dot = halves[i].getIcon() == null ? 0 : DOT_SIZE + DOT_GAP;
			if (text + dot + 2 * TOGGLE_AIR > widths[i])
			{
				return false;
			}
		}
		return true;
	}

	/** Whether half {@code index} is the lit one; pressing the lit half changes nothing. */
	boolean isLit(int index)
	{
		return index == lit;
	}

	private void paintHalf(int index)
	{
		final JLabel half = halves[index];
		final boolean on = isLit(index);
		half.setBackground(on ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
		half.setForeground(on ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
		half.setFont(on ? litFont : unlitFont);
		// A hand only where a press does something.
		half.setCursor(on ? Cursor.getDefaultCursor() : Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	/**
	 * Whether a mouse event is a press that should act: the left button, and not a popup trigger (macOS raises one on a
	 * ctrl-click of the left button).
	 */
	static boolean isPress(MouseEvent e)
	{
		return SwingUtilities.isLeftMouseButton(e) && !e.isPopupTrigger();
	}
}

package com.cabosschecklist;

import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Swaps the sidebar button for one with another picture and keeps the panel open if it was showing. RuneLite only
 * queues a button's removal and addition on the Swing thread while opening a panel runs at once, so an open asked for
 * in the same breath lands on the old tab, and RuneLite then falls back to another plugin's tab when the old one goes.
 * The open is therefore handed to {@code later}, after the add, and it opens the new button only if that button is
 * still the plugin's current one. The button type is generic so the order can be checked without a client.
 *
 * @param <B> the type of a sidebar button
 */
final class IconSwap<B>
{
	private final Consumer<B> remove;
	private final Consumer<B> add;
	private final Consumer<B> open;
	private final Supplier<B> current;
	private final Consumer<Runnable> later;

	/**
	 * @param remove takes a button off the toolbar
	 * @param add puts a button on the toolbar
	 * @param open opens a button's panel
	 * @param current the plugin's current button, or null when it has none
	 * @param later runs a task after the toolbar's queued work (Swing's invokeLater)
	 */
	IconSwap(Consumer<B> remove, Consumer<B> add, Consumer<B> open, Supplier<B> current, Consumer<Runnable> later)
	{
		this.remove = remove;
		this.add = add;
		this.open = open;
		this.current = current;
		this.later = later;
	}

	/** Removes {@code old}, adds {@code next}, and, when the panel was showing, opens {@code next} afterwards. */
	void swap(B old, B next, boolean wasShowing)
	{
		remove.accept(old);
		add.accept(next);
		if (wasShowing)
		{
			later.accept(() ->
			{
				if (current.get() == next)
				{
					open.accept(next);
				}
			});
		}
	}
}

package com.cabosschecklist;

import java.awt.Cursor;
import java.awt.Color;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JLabel;
import net.runelite.client.ui.ColorScheme;

/** A link word: grey, white under the mouse, a hand cursor, acting on a left press. */
final class LinkLabel extends JLabel
{
	LinkLabel(String word, float size, Runnable action)
	{
		super(word);
		setFont(ViewParts.plain(size));
		setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (HalfToggle.isPress(e))
				{
					action.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				setForeground(Color.WHITE);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			}
		});
	}
}

package com.cabosschecklist;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * The Manual view: the player's marks in one or two groups, each row holding the boss with a link that removes the mark
 * and a line saying which colour the mark shows, instead of which, and how far the account is. Rebuilt on every update.
 * Choice: the caption sits 2 px above its first row; the note's labels sit side by side, the spaces in their texts.
 */
final class ManualView
{
	/** The space between groups, in px. */
	private static final int GROUP_GAP = 8;
	/** The space between rows, and between a caption and its first row, in px. */
	private static final int ROW_GAP = 2;
	/** The space between a caption and its link, in px. */
	private static final int LINK_GAP = 8;

	private final MarkActions actions;
	private final ScrollColumn column = new ScrollColumn();
	private final JScrollPane pane = column.pane();

	ManualView(MarkActions actions)
	{
		this.actions = actions;
	}

	/** The scroll pane to place in the panel. */
	JScrollPane pane()
	{
		return pane;
	}

	/** Replaces the groups with one grey line. */
	void showLoggedOut()
	{
		column.removeAll();
		final JLabel line = ViewParts.centred("Log in to see your marks", ViewParts.plain(12f), ColorScheme.LIGHT_GRAY_COLOR);
		line.setBorder(new EmptyBorder(16, 0, 0, 0));
		column.add(line);
		finish();
	}

	/** Shows the view's marks, or the empty state when it has none. */
	void show(ChecklistView view)
	{
		column.removeAll();
		if (view.markCount == 0)
		{
			final JPanel empty = new JPanel();
			empty.setLayout(new BoxLayout(empty, BoxLayout.Y_AXIS));
			empty.setOpaque(false);
			empty.setBorder(new EmptyBorder(16, 0, 0, 0));
			empty.add(ViewParts.centred("No marks yet", ViewParts.bold(12f), Color.WHITE));
			empty.add(Box.createVerticalStrut(ROW_GAP));
			empty.add(ViewParts.centred("Tick or untick a boss to add a mark", ViewParts.plain(11f),
				ColorScheme.LIGHT_GRAY_COLOR));
			column.add(empty);
			finish();
			return;
		}
		if (view.autoDetect)
		{
			addGroup(view.group(Marks.Group.DIFFERENT), "Your marks override your account", false);
			addGroup(view.group(Marks.Group.SAME), "Same as your account", true);
		}
		else
		{
			addGroup(view.marked(), "Your marks", false);
		}
		finish();
	}

	private void finish()
	{
		column.revalidate();
		column.repaint();
	}

	/** One line: {@code left} at the start, {@code right} (when not null) at the end. */
	private static JPanel line(JLabel left, JLabel right)
	{
		final JPanel line = ViewParts.capped(new BorderLayout(LINK_GAP, 0));
		line.setOpaque(false);
		line.add(left, BorderLayout.CENTER);
		if (right != null)
		{
			line.add(right, BorderLayout.EAST);
		}
		return line;
	}

	/** A group under its caption; nothing when it has no rows. */
	private void addGroup(List<ChecklistView.Boss> bosses, String caption, boolean withRemoveAll)
	{
		if (bosses.isEmpty())
		{
			return;
		}
		column.add(Box.createVerticalStrut(GROUP_GAP));
		JLabel removeAll = null;
		if (withRemoveAll)
		{
			final List<Integer> ids = new ArrayList<>();
			for (ChecklistView.Boss boss : bosses)
			{
				ids.add(boss.id);
			}
			removeAll = new LinkLabel("Remove all", 11f, () -> actions.remove(ids));
		}
		column.add(line(ViewParts.label(caption + " (" + bosses.size() + ")", ViewParts.bold(11f), Color.WHITE),
			removeAll));
		for (ChecklistView.Boss boss : bosses)
		{
			column.add(Box.createVerticalStrut(ROW_GAP));
			column.add(row(boss));
		}
	}

	/** A boss's row: its name and the remove sign, then a line saying what the mark does and the account's progress. */
	private JPanel row(ChecklistView.Boss boss)
	{
		final JLabel name = ViewParts.label(boss.label, ViewParts.bold(12f), Color.WHITE);
		name.setToolTipText(boss.label);
		final LinkLabel remove = new LinkLabel("\u00d7", 12f, () -> actions.remove(Collections.singletonList(boss.id)));
		remove.setToolTipText("Remove this mark");

		final JPanel note = new JPanel(new GridBagLayout());
		note.setOpaque(false);
		final List<JLabel> parts = new ArrayList<>();
		parts.add(ViewParts.label(boss.shownWord(), ViewParts.plain(11f), ViewParts.colourOf(boss.shade)));
		parts.add(ViewParts.quiet(boss.overrides() ? " instead of " : " either way"));
		if (boss.overrides())
		{
			parts.add(ViewParts.label(boss.unmarkedWord(), ViewParts.plain(11f),
				ViewParts.colourOf(boss.unmarkedShade)));
		}
		final JLabel progress = ViewParts.quiet(" \u00b7 " + boss.accountText());
		progress.setToolTipText(boss.accountLine());
		parts.add(progress);
		final GridBagConstraints at = new GridBagConstraints();
		at.anchor = GridBagConstraints.WEST;
		at.gridx = 0;
		at.gridy = 0;
		for (JLabel part : parts)
		{
			note.add(part, at);
			at.gridx++;
		}
		at.weightx = 1;
		note.add(Box.createHorizontalGlue(), at);

		final JPanel top = line(name, remove);
		final JPanel lines = new JPanel(new BorderLayout());
		lines.setOpaque(false);
		lines.add(top, BorderLayout.NORTH);
		lines.add(note, BorderLayout.CENTER);

		final JPanel row = ViewParts.capped(new BorderLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));
		row.add(lines, BorderLayout.CENTER);
		return row;
	}
}

package com.cabosschecklist;

/**
 * A player's mark on one boss: it shows green ({@code DONE}) or never green ({@code NOT_DONE}) whatever the account
 * says.
 */
enum Mark
{
	DONE(true, "done"),
	NOT_DONE(false, "not-done");

	private final boolean done;
	private final String token;

	Mark(boolean done, String token)
	{
		this.done = done;
		this.token = token;
	}

	/** Whether the mark says the boss is done (green). */
	boolean done()
	{
		return done;
	}

	/** The word stored in the profile for this mark. */
	String token()
	{
		return token;
	}

	/** The mark with the given answer. */
	static Mark of(boolean done)
	{
		return done ? DONE : NOT_DONE;
	}
}

package com.cabosschecklist;

import java.util.List;
import java.util.Map;

/** What the sidebar's boxes and links do to the player's marks; every call is made on the EDT. */
interface MarkActions
{
	/** Flips the green of boss {@code id}, keeping a mark only while the choice differs from the account. */
	void flip(int id);

	/** Removes the marks of the given bosses. */
	void remove(List<Integer> ids);

	/** Stores the overriding marks the player has looked at. */
	void remember(Map<Integer, Mark> seen);
}

package com.cabosschecklist;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.font.TextAttribute;
import java.awt.geom.RoundRectangle2D;
import java.util.Collections;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;

/**
 * The small pill "MANUAL" on the boss card: bold 9 px capitals with a little letter spacing, fully rounded ends.
 * Never filled: a 1 px outline and letters, orange when strong (the mark overrides the account's progress), grey when
 * not. Not opaque.
 */
final class MarkTag extends JComponent
{
	/** The words on the pill. */
	static final String TEXT = "MANUAL";
	/** Air left and right of the letters, in px. */
	private static final int SIDE = 6;
	/** Air above and below the letters, in px. */
	private static final int UPDOWN = 2;
	private static final Color OUTLINE = new Color(0x6A6A6A);
	private static final Color QUIET_LETTERS = new Color(0xC8C8C8);

	/** Whether the outline and letters are orange (strong) rather than grey; read by tests. */
	boolean strong;

	MarkTag()
	{
		setOpaque(false);
		setFont(ViewParts.bold(9f).deriveFont(Collections.singletonMap(TextAttribute.TRACKING, 0.08f)));
		final Dimension size = pillSize();
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
	}

	/** Sets the orange (strong) or grey look and draws the pill again. */
	void setStrong(boolean strong)
	{
		this.strong = strong;
		repaint();
	}

	private Dimension pillSize()
	{
		final FontMetrics metrics = getFontMetrics(getFont());
		final int width = (int) Math.ceil(getFont().getStringBounds(TEXT, metrics.getFontRenderContext()).getWidth());
		return new Dimension(width + 2 * SIDE, metrics.getHeight() + 2 * UPDOWN);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		final Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			final int width = getWidth();
			final int height = getHeight();
			g.setColor(strong ? ColorScheme.BRAND_ORANGE : OUTLINE);
			g.draw(new RoundRectangle2D.Float(0.5f, 0.5f, width - 1, height - 1, height - 1, height - 1));
			g.setColor(strong ? ColorScheme.BRAND_ORANGE : QUIET_LETTERS);
			final Font font = getFont();
			g.setFont(font);
			final FontMetrics metrics = g.getFontMetrics();
			final double textWidth = font.getStringBounds(TEXT, g.getFontRenderContext()).getWidth();
			g.drawString(TEXT, (float) ((width - textWidth) / 2), (height - metrics.getHeight()) / 2f + metrics.getAscent());
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.cabosschecklist;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The rules for a player's marks, with no RuneLite types so they are tested without a client: how they are stored, when
 * a boss shows green, what a click on its box does, and which Manual group a mark falls in.
 */
final class Marks
{
	private Marks()
	{
	}

	/** Where a mark is listed in the Manual view. */
	enum Group
	{
		/** A mark whose answer differs from what the account alone gives. */
		DIFFERENT,
		/** A mark whose answer is what the account alone gives. */
		SAME
	}

	/**
	 * Reads the stored marks, "id=token" entries split on commas. An entry whose id is not an int of 1 or more, or whose
	 * word is not a mark, is skipped; a later entry for the same id wins.
	 */
	static Map<Integer, Mark> parse(String stored)
	{
		final Map<Integer, Mark> marks = new HashMap<>();
		if (stored != null && !stored.trim().isEmpty())
		{
			for (String entry : stored.split(",", -1))
			{
				final int at = entry.indexOf('=');
				if (at < 0)
				{
					continue;
				}
				final Mark mark = byToken(entry.substring(at + 1).trim());
				final Integer id = parseId(entry.substring(0, at).trim());
				if (mark != null && id != null)
				{
					marks.put(id, mark);
				}
			}
		}
		return Collections.unmodifiableMap(marks);
	}

	private static Integer parseId(String text)
	{
		try
		{
			final int id = Integer.parseInt(text);
			return id >= 1 ? id : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static Mark byToken(String token)
	{
		// 0.0.1 and 0.0.2 also wrote "done-kept" and "not-done-kept"; they read as the plain marks.
		if (token.endsWith("-kept"))
		{
			return byToken(token.substring(0, token.length() - "-kept".length()));
		}
		for (Mark mark : Mark.values())
		{
			if (mark.token().equals(token))
			{
				return mark;
			}
		}
		return null;
	}

	/** The stored form of {@code marks}: "id=token" joined by commas, ids ascending; "" when there are none. */
	static String format(Map<Integer, Mark> marks)
	{
		final List<Integer> ids = new ArrayList<>(marks.keySet());
		Collections.sort(ids);
		final StringBuilder out = new StringBuilder();
		for (int id : ids)
		{
			if (out.length() > 0)
			{
				out.append(',');
			}
			out.append(id).append('=').append(marks.get(id).token());
		}
		return out.toString();
	}

	/** Whether a Monster name shows green: "All" (0) never does; a mark wins; else the account alone, if followed. */
	static boolean isGreen(int id, boolean autoDetect, Set<Integer> complete, Map<Integer, Mark> marks)
	{
		if (id < 1)
		{
			return false;
		}
		final Mark mark = marks.get(id);
		if (mark != null)
		{
			return mark.done();
		}
		return autoDetect && complete.contains(id);
	}

	/** What a click on a boss's box leaves: null for no mark (the choice equals the account alone), else the mark. */
	static Mark flip(boolean greenNow, boolean accountGreen, boolean autoDetect)
	{
		final boolean want = !greenNow;
		final boolean baseline = autoDetect && accountGreen;
		return want == baseline ? null : Mark.of(want);
	}

	/** Which Manual group {@code mark} is listed in, given the boss's counted tasks and its done tasks. */
	static Group groupOf(Mark mark, int total, int done)
	{
		final boolean accountGreen = total > 0 && done == total;
		return mark.done() == accountGreen ? Group.SAME : Group.DIFFERENT;
	}

	/** The marks that take effect: {@code marks} itself while the sidebar button is shown, else none. */
	static Map<Integer, Mark> inUse(Map<Integer, Mark> marks, boolean sidebarShown)
	{
		return sidebarShown ? marks : Collections.emptyMap();
	}

	/**
	 * The seen marks after the player has (looking) or has not looked at the Manual tab: a copy of {@code overriding}
	 * when looking, else the entries of {@code seen} that are still the same mark in {@code overriding}.
	 */
	static Map<Integer, Mark> seenAfter(Map<Integer, Mark> seen, Map<Integer, Mark> overriding, boolean looking)
	{
		final Map<Integer, Mark> next = new HashMap<>();
		if (looking)
		{
			next.putAll(overriding);
		}
		else
		{
			for (Map.Entry<Integer, Mark> entry : seen.entrySet())
			{
				if (entry.getValue() == overriding.get(entry.getKey()))
				{
					next.put(entry.getKey(), entry.getValue());
				}
			}
		}
		return Collections.unmodifiableMap(next);
	}

	/** Whether some overriding mark has not been seen: it has no equal entry in {@code seen}. */
	static boolean hasUnseen(Map<Integer, Mark> seen, Map<Integer, Mark> overriding)
	{
		for (Map.Entry<Integer, Mark> entry : overriding.entrySet())
		{
			if (seen.get(entry.getKey()) != entry.getValue())
			{
				return true;
			}
		}
		return false;
	}
}

