package com.cabosschecklist;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** The icon swap: the old button goes first; the panel is opened again only after the swap, if still current. */
public class IconSwapTest
{
	private static final String OLD = "old";
	private static final String NEW = "new";

	/** Records the toolbar's calls and holds what was handed to {@code later}. */
	private static final class Fake
	{
		final List<String> calls = new ArrayList<>();
		final List<Runnable> queued = new ArrayList<>();
		String current = NEW;

		IconSwap<String> swap()
		{
			return new IconSwap<>(
				b -> calls.add("remove " + b),
				b -> calls.add("add " + b),
				b -> calls.add("open " + b),
				() -> current,
				queued::add);
		}
	}

	@Test
	public void theOldButtonGoesBeforeTheNewOneComes()
	{
		final Fake fake = new Fake();
		fake.swap().swap(OLD, NEW, false);
		assertEquals(Arrays.asList("remove old", "add new"), fake.calls);
	}

	@Test
	public void aShowingPanelIsOpenedAgainOnlyAfterTheSwap()
	{
		final Fake fake = new Fake();
		fake.swap().swap(OLD, NEW, true);
		assertEquals(Arrays.asList("remove old", "add new"), fake.calls);
		assertEquals(1, fake.queued.size());
		fake.queued.get(0).run();
		assertEquals(Arrays.asList("remove old", "add new", "open new"), fake.calls);
	}

	@Test
	public void aHiddenPanelIsNotOpened()
	{
		final Fake fake = new Fake();
		fake.swap().swap(OLD, NEW, false);
		assertTrue(fake.queued.isEmpty());
		assertEquals(2, fake.calls.size());
	}

	@Test
	public void aButtonThatIsNoLongerCurrentIsNotOpened()
	{
		final Fake changed = new Fake();
		changed.swap().swap(OLD, NEW, true);
		changed.current = "another";
		changed.queued.get(0).run();
		assertEquals(Arrays.asList("remove old", "add new"), changed.calls);

		final Fake gone = new Fake();
		gone.swap().swap(OLD, NEW, true);
		gone.current = null;
		gone.queued.get(0).run();
		assertEquals(Arrays.asList("remove old", "add new"), gone.calls);
	}
}

package com.cabosschecklist;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class MarkTagTest
{
	/** The tag painted at its preferred size into a transparent image. */
	private static BufferedImage paint(MarkTag tag)
	{
		final Dimension size = tag.getPreferredSize();
		tag.setSize(size);
		final BufferedImage image = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		tag.paint(g);
		g.dispose();
		return image;
	}

	private static boolean isOrange(Color c)
	{
		return c.getRed() > 200 && c.getGreen() >= 110 && c.getGreen() <= 170 && c.getBlue() < 60;
	}

	private static boolean isGrey(Color c)
	{
		final int high = Math.max(c.getRed(), Math.max(c.getGreen(), c.getBlue()));
		final int low = Math.min(c.getRed(), Math.min(c.getGreen(), c.getBlue()));
		return high - low <= 12;
	}

	@Test
	public void theTagIsAnOutlineOrangeWhenStrong()
	{
		final MarkTag strong = new MarkTag();
		final Dimension size = strong.getPreferredSize();
		assertTrue("height " + size.height, size.height >= 12 && size.height <= 18);
		assertTrue("width " + size.width, size.width >= 30 && size.width <= 70);
		strong.setStrong(true);
		final BufferedImage orange = paint(strong);
		final Color top = new Color(orange.getRGB(size.width / 2, 0), true);
		assertTrue("alpha " + top.getAlpha(), top.getAlpha() >= 200);
		assertTrue("orange " + top, isOrange(top));
		assertEquals(0, new Color(orange.getRGB(3, size.height / 2), true).getAlpha());

		final MarkTag quiet = new MarkTag();
		quiet.setStrong(false);
		final BufferedImage grey = paint(quiet);
		final Color edge = new Color(grey.getRGB(size.width / 2, 0), true);
		assertTrue("alpha " + edge.getAlpha(), edge.getAlpha() >= 200);
		assertFalse("not orange " + edge, isOrange(edge));
		assertTrue("grey " + edge, isGrey(edge));
		assertEquals(0, new Color(grey.getRGB(3, size.height / 2), true).getAlpha());
	}
}

package com.cabosschecklist;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class MarksTest
{
	private static Set<Integer> set(Integer... ids)
	{
		return new HashSet<>(Arrays.asList(ids));
	}

	private static Map<Integer, Mark> map(Object... pairs)
	{
		final Map<Integer, Mark> result = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			result.put((Integer) pairs[i], (Mark) pairs[i + 1]);
		}
		return result;
	}

	@Test
	public void parseAndFormatRoundTrip()
	{
		final Map<Integer, Mark> parsed = Marks.parse("3=done,7=not-done");
		assertEquals(map(3, Mark.DONE, 7, Mark.NOT_DONE), parsed);
		assertEquals("3=done,7=not-done", Marks.format(parsed));
	}

	@Test
	public void oldKeptWordsReadAsPlain()
	{
		final Map<Integer, Mark> parsed = Marks.parse("3=done-kept,4=not-done-kept");
		assertEquals(map(3, Mark.DONE, 4, Mark.NOT_DONE), parsed);
		assertEquals("3=done,4=not-done", Marks.format(parsed));
	}

	@Test
	public void parseSkipsJunk()
	{
		assertTrue(Marks.parse(null).isEmpty());
		assertTrue(Marks.parse("").isEmpty());
		assertEquals(map(20, Mark.DONE), Marks.parse("x=done,0=done,-3=done,19=maybe,19,=done, 20 = done "));
		assertEquals(map(19, Mark.NOT_DONE), Marks.parse("19=done,19=not-done"));
	}

	@Test
	public void formatEmptyIsEmpty()
	{
		assertEquals("", Marks.format(Collections.<Integer, Mark>emptyMap()));
	}

	@Test
	public void flipFollowsTheRule()
	{
		assertEquals(Mark.NOT_DONE, Marks.flip(true, true, true));
		assertNull(Marks.flip(false, true, true));
		assertEquals(Mark.DONE, Marks.flip(false, false, true));
		assertNull(Marks.flip(true, false, true));
		assertEquals(Mark.DONE, Marks.flip(false, true, false));
		assertNull(Marks.flip(true, true, false));
	}

	@Test
	public void greenFromAutoOrMark()
	{
		final Map<Integer, Mark> none = Collections.emptyMap();
		assertTrue(Marks.isGreen(19, true, set(19), none));
		assertFalse(Marks.isGreen(19, false, set(19), none));
		assertTrue(Marks.isGreen(19, false, set(), map(19, Mark.DONE)));
		assertFalse(Marks.isGreen(19, true, set(19), map(19, Mark.NOT_DONE)));
		assertFalse(Marks.isGreen(0, true, set(0), map(0, Mark.DONE)));
		assertFalse(Marks.isGreen(-1, true, set(), none));
	}

	@Test
	public void groupsFollowTheRule()
	{
		assertEquals(Marks.Group.DIFFERENT, Marks.groupOf(Mark.DONE, 8, 5));
		assertEquals(Marks.Group.SAME, Marks.groupOf(Mark.DONE, 8, 8));
		assertEquals(Marks.Group.DIFFERENT, Marks.groupOf(Mark.NOT_DONE, 8, 8));
		assertEquals(Marks.Group.SAME, Marks.groupOf(Mark.NOT_DONE, 8, 5));
		assertEquals(Marks.Group.DIFFERENT, Marks.groupOf(Mark.DONE, 0, 0));
		assertEquals(Marks.Group.SAME, Marks.groupOf(Mark.NOT_DONE, 0, 0));
	}

	@Test
	public void tokensAndOf()
	{
		assertEquals("done", Mark.DONE.token());
		assertEquals("not-done", Mark.NOT_DONE.token());
		assertEquals(Mark.DONE, Mark.of(true));
		assertEquals(Mark.NOT_DONE, Mark.of(false));
		assertEquals(2, Mark.values().length);
	}

	@Test
	public void marksAreIgnoredWhileTheSidebarIsHidden()
	{
		final Map<Integer, Mark> marks = map(19, Mark.DONE);
		assertEquals(marks, Marks.inUse(marks, true));
		assertTrue(Marks.inUse(marks, false).isEmpty());
		assertFalse(Marks.isGreen(19, true, set(), Marks.inUse(map(19, Mark.DONE), false)));
		assertTrue(Marks.isGreen(19, true, set(19), Marks.inUse(map(19, Mark.NOT_DONE), false)));
	}

	@Test
	public void seenAfterFollowsTheRule()
	{
		final Map<Integer, Mark> seen = map(5, Mark.DONE, 9, Mark.DONE);
		final Map<Integer, Mark> overriding = map(5, Mark.DONE, 72, Mark.NOT_DONE);
		assertEquals(map(5, Mark.DONE), Marks.seenAfter(seen, overriding, false));
		assertEquals(overriding, Marks.seenAfter(seen, overriding, true));
		assertTrue(Marks.seenAfter(map(5, Mark.DONE), map(5, Mark.NOT_DONE), false).isEmpty());
		assertTrue(Marks.seenAfter(map(), map(), true).isEmpty());
	}

	@Test
	public void unseenFollowsTheRule()
	{
		assertFalse(Marks.hasUnseen(map(5, Mark.DONE), map(5, Mark.DONE)));
		assertTrue(Marks.hasUnseen(map(5, Mark.DONE), map(5, Mark.DONE, 72, Mark.NOT_DONE)));
		assertFalse(Marks.hasUnseen(map(), map()));
		assertTrue(Marks.hasUnseen(map(5, Mark.DONE), map(5, Mark.NOT_DONE)));
		assertFalse(Marks.hasUnseen(map(5, Mark.DONE, 9, Mark.DONE), map(5, Mark.DONE)));
	}
}

package com.cabosschecklist;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** {@link NavIcon}, in memory: the size, the coin exactly as {@link CoinGlyph} draws it, the picture clear of it. */
public class NavIconTest
{
	/** The coin's centre and the farthest its jittered rim reaches from it, with a pixel of margin. */
	private static final double COIN_CENTRE = 4.5;
	private static final double CLEAR_DISTANCE = 6.0;

	private static BufferedImage coinAlone()
	{
		final BufferedImage img = new BufferedImage(NavIcon.SIZE, NavIcon.SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			CoinGlyph.paint(g);
		}
		finally
		{
			g.dispose();
		}
		return img;
	}

	@Test
	public void theIconIsSixteenBySixteenArgb()
	{
		final BufferedImage icon = NavIcon.create();
		assertEquals(16, icon.getWidth());
		assertEquals(16, icon.getHeight());
		assertEquals(BufferedImage.TYPE_INT_ARGB, icon.getType());
	}

	@Test
	public void theCoinIsDrawnPixelForPixelAsTheCoinGlyphDrawsIt()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int coinPixels = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if ((coin.getRGB(x, y) >>> 24) != 0)
				{
					coinPixels++;
					assertEquals("coin pixel " + x + "," + y, coin.getRGB(x, y), icon.getRGB(x, y));
				}
			}
		}
		assertTrue("the coin drew something", coinPixels > 0);
	}

	@Test
	public void thePictureLiesClearOfTheCoinsCircle()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int pictureOnly = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if (icon.getRGB(x, y) != coin.getRGB(x, y))
				{
					pictureOnly++;
					final double dx = x + 0.5 - COIN_CENTRE;
					final double dy = y + 0.5 - COIN_CENTRE;
					assertTrue("picture pixel " + x + "," + y + " is too near the coin",
						Math.sqrt(dx * dx + dy * dy) >= CLEAR_DISTANCE);
				}
			}
		}
		assertTrue("the picture drew something", pictureOnly > 0);
	}

	/**
	 * A stand-in for RuneLite's picture of the book: 36 x 32 and clear, but for a solid 30 x 27 block at (3, 2), the size
	 * the game's book has inside its picture. No picture of the game's is used in the tests.
	 */
	private static BufferedImage itemPicture()
	{
		final BufferedImage item = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		for (int y = 2; y < 29; y++)
		{
			for (int x = 3; x < 33; x++)
			{
				item.setRGB(x, y, 0xFF5C3F3D);
			}
		}
		return item;
	}

	@Test
	public void theBookIconKeepsTheCoinWhole()
	{
		final BufferedImage icon = NavIcon.withBook(itemPicture());
		final BufferedImage coin = coinAlone();
		assertEquals(16, icon.getWidth());
		assertEquals(16, icon.getHeight());
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if ((coin.getRGB(x, y) >>> 24) == 255)
				{
					assertEquals("coin pixel " + x + "," + y, coin.getRGB(x, y), icon.getRGB(x, y));
				}
			}
		}
	}

	/** Cut to its outline first, the 30 x 27 book fills its 12 x 11 box (uncut, its clear margins would leave it 10 wide). */
	@Test
	public void theBookIsCutToItsOutlineAndFillsItsBox()
	{
		final BufferedImage icon = NavIcon.withBook(itemPicture());
		final BufferedImage coin = coinAlone();
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				final boolean inBox = x >= 4 && y >= 5;
				if (!inBox && (coin.getRGB(x, y) >>> 24) == 0)
				{
					assertEquals("pixel " + x + "," + y + " is outside the book's box and stays clear", 0, icon.getRGB(x, y) >>> 24);
				}
			}
		}
		assertEquals("the box's left column holds book", 255, icon.getRGB(4, 15) >>> 24);
		assertEquals("the box's right column holds book", 255, icon.getRGB(15, 15) >>> 24);
		assertEquals("the box's top row holds book", 255, icon.getRGB(15, 5) >>> 24);
	}

	@Test
	public void anEmptyPictureGivesTheCoinAlone()
	{
		final BufferedImage icon = NavIcon.withBook(new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB));
		final BufferedImage coin = coinAlone();
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				assertEquals("pixel " + x + "," + y, coin.getRGB(x, y), icon.getRGB(x, y));
			}
		}
	}

	/** The chosen picture (2026-11-08, number 1 of 20): CA in the brand orange, at x 9 to 15 and y 11 to 15, nothing else. */
	@Test
	public void thePictureIsTheLettersCa()
	{
		final String[] letters = {"###.###", "#...#.#", "#...###", "#...#.#", "###.#.#"};
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				final boolean letter = x >= 9 && y >= 11 && letters[y - 11].charAt(x - 9) == '#';
				if (letter)
				{
					assertEquals("letter pixel " + x + "," + y, ColorScheme.BRAND_ORANGE.getRGB(), icon.getRGB(x, y));
				}
				else if ((coin.getRGB(x, y) >>> 24) == 0)
				{
					assertEquals("pixel " + x + "," + y + " stays clear", 0, icon.getRGB(x, y) >>> 24);
				}
			}
		}
	}

	@Test
	public void theBookAloneFillsTheIcon()
	{
		final BufferedImage icon = NavIcon.bookOnly(itemPicture());
		assertEquals(16, icon.getWidth());
		assertEquals(16, icon.getHeight());
		for (int x = 0; x < NavIcon.SIZE; x++)
		{
			assertEquals("row 0, column " + x, 0, icon.getRGB(x, 0) >>> 24);
			assertEquals("row 15, column " + x, 0, icon.getRGB(x, 15) >>> 24);
		}
		assertEquals(255, icon.getRGB(0, 1) >>> 24);
		assertEquals(255, icon.getRGB(15, 1) >>> 24);
		assertEquals(255, icon.getRGB(0, 14) >>> 24);
		assertEquals(255, icon.getRGB(15, 14) >>> 24);
		final BufferedImage clear = NavIcon.bookOnly(new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB));
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				assertEquals("empty picture pixel " + x + "," + y, 0, clear.getRGB(x, y) >>> 24);
			}
		}
	}

	private static void assertSame(String what, BufferedImage expected, BufferedImage actual)
	{
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
