			SupportLinks.GITHUB_PROFILE_URL, PLUGIN_URL);
		final List<JLabel> marks = marksOf((JPanel) links(NAME, "1.0.9").header().getComponent(2));

		for (int i = 0; i < marks.size(); i++)
		{
